const group4Commentaries = {
    1: "Այս նշանը ցույց է տալիս ընդհանուր օգտագործման տրանսպորտային միջոցների համար նախատեսված գոտի։ Աջ շրջադարձի ժամանակ կարելի է մտնել այդ գոտի միայն շրջադարձը կատարելու համար, եթե այն երթևեկելի մասից բաժանված չէ հոծ գծով․ հոծ գիծը հատել չի թույլատրվում։ Նկարում՝ [[5.14]]։",
    2: "Եռանկյուն նախազգուշացնող նշանի վրա պատկերված հետիոտնը և զեբրան զգուշացնում են հետիոտնային անցման մասին։ Այն պահանջում է հատկապես ուշադիր լինել և անհրաժեշտության դեպքում զիջել հետիոտներին, բայց ինքնին հետիոտնային անցքի տեղը չի նշում։ Նկարում՝ [[1.22]]։",
    3: "Պետք է համեմատել մեքենաների միջև նվազագույն հեռավորության նշանը։ Երրորդ նշանի վրա պատկերված մեքենաների միջակայքն ու 70 մ արժեքը ցույց են տալիս արգելվող նվազագույն միջտարածությունը․ դա հենց այդպիսի սահմանափակում է, ի տարբերություն չափերի կամ զանգվածի սահմանափակումների։ Նկարի բոլոր նշանները՝ [[3.14]], [[3.11]], [[3.16]], [[8.2.1]], [[6.2]]։",
    4: "Բնակավայրում նախազգուշացնող նշանները սովորաբար տեղադրվում են վտանգավոր հատվածից 50–100 մ առաջ, որպեսզի վարորդը հասցնի արձագանքել։ Նկարում համեմատվող նշանները վերաբերում են երկաթուղային գծանցին, լուսացուցային կարգավորմանը, հավասարազոր ճանապարհների հատմանը և այլ վտանգներին։ Նկարի նշանները՝ [[1.1]], [[1.2]], [[1.6]], [[1.8]], [[1.33]]։",
    5: "Կարմիր եզրագծով շրջանաձև նշանի վրա տրակտորի պատկերն արգելում է տրակտորների և ինքնագնաց մեքենաների երթևեկությունը։ Այն չի նշանակում բոլոր մեխանիկական տրանսպորտային միջոցների կամ բոլոր տրանսպորտային միջոցների ընդհանուր արգելք։ Նկարում՝ [[3.6]]։",
    6: "Հանդիպակաց երթևեկության առավելության նշանը ցույց է տալիս, որ նեղ հատվածում վարորդը պետք է զիջի հանդիպակացին։ Նկարի 3-րդ նշանը՝ կարմիր սլաքով շրջանաձև նշանը, հենց այդ պահանջն է սահմանում, ոչ թե «Զիջեք ճանապարհը» կամ «Կանգառն արգելվում է» նշանները։ Նկարի նշանները՝ [[3.3]], [[2.4]], [[2.6]], [[1.6]], [[4.2.3]]։",
    7: "Հավասարազոր ճանապարհների խաչմերուկի մասին նախազգուշացնում է խաչաձև ճանապարհը պատկերող եռանկյուն նշանը։ Նկարի մյուս նշանները ցույց են տալիս շրջանցման, զիջման, կից ճանապարհի կամ հանդիպակաց հոսքի իրավիճակներ։ Նկարի նշանները՝ [[1.6]], [[1.2]], [[2.4]], [[1.21]], [[1.6]]։",
    8: "Ճանապարհի ուղղությամբ երթևեկությունը սահմանափակող արգելող նշանը պետք է տեղադրվի հենց այն խաչմերուկից առաջ, որտեղ պահանջը պետք է կատարվի։ Այստեղ ճիշտն աջ շրջադարձն արգելող նշանն է․ նախազգուշացնող նշանները տեղադրվում են վտանգավոր հատվածից որոշ հեռավորության վրա։ Նկարի նշանները՝ [[1.6]], [[3.18.1]], [[1.10]], [[1.6]], [[1.9]]։",
    9: "Մուտքն արգելող նշանի հետ սլաքով ցուցանակը սահմանում է, թե որ ուղղությամբ է գործում արգելքը։ Այդ համադրությունը չի վերացնում մյուս թույլատրելի շարժումները, ուստի պետք է հետևել նաև հատվող ճանապարհի նշաններին ու գծանշմանը։ Նկարում՝ [[3.1]], [[8.3.2]]։",
    10: "Հանդիպակաց երթևեկության նկատմամբ առավելություն տվող նշանը նշվում է կապույտ շրջանով և սպիտակ սլաքով՝ վարորդին թույլ տալով առաջինն անցնել նեղ հատվածը։ Չորրորդն է այդ նշանը․ մնացածները նախազգուշացնում են երկկողմ երթևեկության մասին, տալիս կամ սահմանափակում առավելությունը կամ ցույց տալիս գոտիների ուղղությունները։ Նկարի նշանները՝ [[1.21]], [[2.6]], [[2.1]], [[2.7]], [[5.15.1]]։",
    11: "Վտանգավոր շրջադարձերի նշանի տակ հեռավորության կամ հատվածի երկարության ցուցանակը ցույց է տալիս, թե որքան ճանապարհ է ընդգրկում վտանգավոր ոլորանների հաջորդականությունը։ Այստեղ ցուցանակը վերաբերում է հատվածի ամբողջ երկարությանը, ոչ թե առաջին շրջադարձի մեկնարկին։ Նկարում՝ [[1.12.1]], [[8.2.1]]։",
    12: "Մոտոցիկլի պատկերով կարմիր շրջանաձև նշանն արգելում է մոտոցիկլների երթևեկությունը։ Աջ ուղղված սլաքով լրացուցիչ ցուցանակը սահմանափակումն ուղղորդում է դեպի աջ, հետևաբար նշանների համադրությունը նշանակում է աջ շարժումն արգելված է։ Նկարում՝ [[3.5]], [[8.3.1]]։",
    13: "Ամսվա զույգ օրերին կայանելն արգելող նշանը կապույտ շրջանի վրա երկու հատվող շեղ գիծ ունեցող նշանն է։ Մեկ շեղ գիծը վերաբերում է ամսվա կենտ օրերին, իսկ հավելյալ ցուցանակներն առանձին կարող են սահմանել աշխատանքային կամ հանգստյան օրերի կիրառումը։ Նկարի նշանները՝ [[3.28]], [[8.5.2]], [[8.5.3]], [[3.28]], [[3.27]]։",
    14: "Կապույտ շրջանաձև նշանը նվազագույն արագության պարտադիր պահանջ է․ վարորդը պետք է ընթանա նշված արագությամբ կամ ավելի արագ, եթե ճանապարհային պայմաններն ու մյուս կանոնները դա թույլ են տալիս։ Կարմիր եզրագծով շրջանը սահմանում է առավելագույնը, իսկ կապույտ քառակուսին առաջարկվող արագություն է։ Նկարում՝ [[4.6]]։",
    15: "Հանդիպակաց երթևեկողին զիջելու պահանջը սահմանում է «Հանդիպակաց երթևեկության առավելություն» նշանը։ Այն վարորդին արգելում է նեղ հատված մտնել, եթե դրանով հանդիպակացին կստիպի կանգնել կամ զիջել։ Նկարի նշանները՝ [[1.21]], [[2.6]], [[2.5]], [[5.15.1]], [[2.7]]։",
    16: "Կապույտ նախնական ցուցիչը ցույց է տալիս, որ երթևեկությունը շուտով կվերադասավորվի այլ երթևեկելի մաս։ Այն նախապես տեղեկացնում է ուղղության փոփոխության մասին, այլ ոչ թե պարզապես արգելքի շրջանցման կամ հանդիպակաց գոտի դուրս գալու։ Նկարում՝ [[6.19.1]]։",
    17: "Հատվող ճանապարհով ընթացող տրանսպորտային միջոցներին զիջելու պահանջը ցույց է տալիս շրջված եռանկյուն «Զիջեք ճանապարհը» նշանը։ Նախազգուշացնող խաչմերուկի նշանը միայն զգուշացնում է, իսկ լուսացույցի կամ հանդիպակաց հոսքի նշանները այլ իրավիճակների համար են։ Նկարի նշանները՝ [[1.6]], [[1.8]], [[2.4]], [[1.33]], [[2.6]]։",
    18: "Նշվածից ոչ պակաս արագություն պարտադրում է կապույտ շրջանաձև նվազագույն արագության նշանը․ նկարում դա 3-րդն է։ Կարմիր շրջանաձև նշանը առավելագույն արագություն է սահմանում, իսկ շեղ գծով նշանը սահմանափակումը դադարեցնում է։ Նկարի նշանները՝ [[3.24]], [[3.25]], [[4.6]], [[4.7]], [[6.2]]։",
    19: "Միակողմ երթևեկությամբ ճանապարհը ցույց է տալիս կապույտ ուղղանկյուն նշանը՝ դեպի վեր ուղղված սպիտակ սլաքով։ Այն տեղեկացնում է ճանապարհի ամբողջ հատվածի երթևեկության ուղղությունը, մինչդեռ կապույտ շրջանը պարտադիր շարժման ուղղություն է սահմանում միայն տվյալ հանգույցում։ Նկարի նշանները՝ [[1.20.2]], [[2.6]], [[5.5]], [[2.7]], [[4.1.1]]։",
    20: "Լրացուցիչ ցուցանակի սլաքները ցույց են տալիս, որ նվազագույն միջտարածության պահանջը կսկսի գործել նշանից 300 մ հետո։ Ուստի այն չի նկարագրում նշանի տեղից սկսվող գոտի, այլ հեռավորություն մինչև սահմանափակման սկիզբը։ Նկարում՝ [[3.16]], [[8.1.1]]։",
    21: "Նշանի պատկերում մեքենան դուրս է գալիս ափի եզրից դեպի ջուրը․ սա զգուշացնում է ճանապարհից դեպի ափ կամ առափ դուրս գալու վտանգի մասին։ Այն կապված չէ կտրուկ վայրէջքի կամ պարզապես թեք ճանապարհի հետ։ Նկարում՝ [[1.10]]։",
    22: "Արգելքի ազդեցության գոտու ավարտը ցույց է տալիս նույն արգելող նշանի վրա երեք շեղ գիծ ունեցող տարբերակը։ Նկարի 4-րդ նշանն այդպիսի ավարտի նշան է, իսկ մյուսները սահմանում են չափի կամ արագության առանձին սահմանափակումներ։ Նկարի նշանները՝ [[3.14]], [[3.11]], [[3.16]], [[3.25]], [[2.5]]։",
    23: "Նախազգուշացնող նշանի հետ կիրառվող ցուցանակը՝ վերև և ներքև ուղղված սլաքներով ու հեռավորությամբ, նշում է վտանգավոր հատվածի երկարությունը։ 4-րդ տարբերակում ցուցադրված 100 մ-ն այդ հատվածի չափն է, ոչ թե մինչև այն մնացած ճանապարհը։ Նկարի նշանները՝ [[6.2]], [[8.1.1]], [[6.9.1]], [[8.2.1]], [[2.5]]։",
    24: "Բեռնատարի պատկերով կապույտ տեղեկատվական նշանը ցույց է տալիս բեռնատար ավտոմոբիլների համար առաջարկվող երթևեկության ուղղությունը։ Այն ուղղորդող տեղեկատվություն է, ոչ թե բոլոր վարորդների համար պարտադիր շրջադարձի հրահանգ։ Նկարում՝ [[6.15.1]]։",
    25: "Հյուրանոցը կամ մոթելը ցույց է տալիս մահճակալի պատկերով սպասարկման նշանը։ Նկարի 3-րդ նշանն է․ խաչով մահճակալը բժշկական օգնության կետ է, իսկ պատառաքաղն ու դանակը՝ սննդի կետ։ Նկարի նշանները՝ [[7.1]], [[7.7]], [[7.9]], [[7.10]], [[7.11]]։",
    26: "Դեղին շրջանակի վրա երեք սև կետերով ճանաչման նշանը ցույց է տալիս, որ մեքենան վարում է խուլ կամ խուլ ու համր վարորդ։ Այն մեքենայի տեխնիկական թերության կամ ընդհանուր վտանգի նշան չէ։ Նկարում՝ [[tsr-9.7]]։",
    27: "Երկրորդ նշանը ցույց է տալիս արագության սահմանափակման ավարտը․ մինչև այն գործում է 50 կմ/ժ առավելագույն արագությունը, իսկ դրանից հետո այդ սահմանափակումը դադարում է։ Կապույտ շրջանի վրա գիծը վերաբերում է նվազագույն արագության ավարտին, իսկ քառակուսին՝ այլ տեսակի գոտուն։ Նկարի նշանները՝ [[3.24]], [[3.25]], [[4.6]], [[4.7]], [[6.2]]։",
    28: "Ճանապարհային աշխատանքների նշանը զգուշացնում է նորոգման մասին, իսկ մեքենայի պատկերով ցուցանակը հստակեցնում է, որ կողնակ դուրս գալը վտանգավոր է։ Այդ պատճառով պետք է խուսափել կողնակ մուտք գործելուց, ոչ թե եզրակացնել, որ հիմնական ճանապարհը փակ է։ Նկարում՝ [[1.25]], [[8.12]]։",
    29: "Վտանգավոր բեռ փոխադրող տրանսպորտային միջոցը պետք է կահավորված լինի համապատասխան ճանաչման նշանով։ Նկարի կարմիր-սպիտակ նշանը վերաբերում է վտանգավոր բեռի փոխադրմանը, ոչ թե երեխաների փոխադրմանը կամ դանդաղընթաց մեքենային։ Նկարում՝ [[tsr-9.10]]։",
    30: "Նախկինում սահմանված բոլոր սահմանափակումների գոտին ավարտող նշանը սպիտակ շրջանի վրա երեք թեք սև գծերով նշանն է։ 4-րդ տարբերակն է․ մյուսները վերացնում են միայն առանձին արգելք կամ սահմանափակում։ Նկարի նշանները՝ [[3.23]], [[3.21]], [[3.25]], [[3.31]], [[2.1]]։",
    31: "«Զիջեք ճանապարհը» նշանի պահանջը կատարված է, երբ վարորդը չի խանգարում հատվող ճանապարհով ընթացողներին և անհրաժեշտության դեպքում կանգնում է։ Նշանը պարտադիր կանգառ չի պահանջում բոլոր դեպքերում․ այն պահանջում է զիջել առաջնահերթություն ունեցող հոսքին։ Նկարում՝ [[2.4]]։",
    32: "Ավտոգնացքի ճանաչման նշանը բաղկացած է երեք նարնջագույն լույսերից, որոնք դասավորված են եռանկյունաձև։ Նկարի աջ մեքենայի վրա հենց այդ երեք լույսերն են, իսկ ձախի մեկ նարնջագույն եռանկյունը այլ ազդանշան է։ Նկարում՝ [[tsr-9.1]]։",
    33: "Հատվող ճանապարհով երթևեկողներին զիջել պարտադրում է 4-րդ՝ շրջված եռանկյուն նշանը։ Խաչմերուկի նախազգուշացումը կամ երկու սլաքներով ցուցանակը ինքնին այդպիսի առաջնահերթության պահանջ չեն սահմանում։ Նկարի նշանները՝ [[8.2.4]], [[1.6]], [[2.6]], [[2.4]], [[3.11]]։",
    34: "Կայանատեղում մեքենան ինչպես կանգնեցնելը ցույց է տալիս համապատասխան լրացուցիչ ցուցանակը։ 3-րդ պատկերում մեքենան կանգնած է կողնակին թեք դիրքով, հետևաբար դա է կայանման ձևը նկարագրող նշանը։ Նկարի նշանները՝ [[8.4.4]], [[8.6.2]], [[8.6.3]], [[8.6.4]], [[8.6.1]]։",
    35: "Ավտոբուսների գոտի մտնել կարելի է ուղևոր նստեցնելու կամ իջեցնելու համար միայն այն դեպքում, երբ գոտին երթևեկելի մասի աջ եզրին է և բաժանված չէ հոծ գծով։ Նշանի առկայությունն ինքնին չի թույլատրում հոծ գիծը հատել։ Նկարում՝ [[5.14]]։",
    36: "Վազանցն արգելող նշանը արգելում է վազանց կատարել, բացառությամբ կանոններում նշված դանդաղընթաց տրանսպորտային միջոցների, լծասայլերի, առանց կողային կցորդի մոտոցիկլների, մոպեդների և հեծանիվների։ Սա բացարձակ արգելք չէ բոլոր տեսակի վազանցների համար։ Նկարում՝ [[3.20]]։",
    37: "Հեծանվային արահետի հետ հատման մասին զգուշացնողը 2-րդ եռանկյուն նշանն է, որի վրա հեծանիվ է պատկերված։ Կապույտ շրջանաձև նշանը հեծանվային արահետ է սահմանում, իսկ կարմիր շրջանը կարող է արգելել հեծանվի երթևեկությունը։ Նկարի նշանները՝ [[4.4]], [[1.24]], [[3.9]], [[5.19.1]], [[3.5]]։",
    38: "Վազանցի արգելման գոտու ավարտը ցույց է տալիս նույն վազանցի արգելքի նշանը՝ երեք թեք գծերով։ Այդ նշանից հետո տվյալ արգելքը դադարում է, բայց վարորդը միևնույն է պետք է պահպանի վազանցի ընդհանուր անվտանգության կանոնները։ Նկարում՝ [[3.21]]։",
    39: "2-րդ նշանը ցույց է տալիս երթևեկության սխեման T-աձև խաչմերուկում՝ ինչպես են միանում ճանապարհները և ուր են ուղղված հոսքերը։ Կապույտ սլաքներով շրջանի նշանը շարժման պարտադիր ուղղություն է, իսկ արգելապատնեշի նշանները ներկայացնում են այլ իրավիճակներ։ Նկարի նշանները՝ [[4.1.6]], [[6.9.3]], [[1.2.1]], [[6.8.1]], [[4.3]]։",
    40: "Կապույտ նշանի վրա կարմիր-սպիտակ փակուղու պատկերն ասում է, որ ճանապարհը միջանցիկ շարունակություն չունի։ Դա տեղեկատվական նշան է և ինքնին չի արգելում մուտքը։ Նկարում՝ [[6.8.1]]։",
    41: "Ավտոմոբիլների համար ճանապարհի նշանը ցույց է տալիս ավտոմոբիլային երթևեկության համար առանձնացված ճանապարհը․ դրա ազդեցության ներքո թույլատրվում է ավտոմոբիլների և մոտոցիկլների երթևեկությունը։ Այն ավտոմայրուղու նշանը չէ, որի կանոնները կարող են ավելի խիստ լինել։ Նկարում՝ [[5.3]]։",
    42: "2-րդ՝ շրջված եռանկյուն նշանը «Զիջեք ճանապարհը» առաջնահերթության նշան է, ոչ թե արգելող նշան։ Մյուս տարբերակները արգելում են ձայնային ազդանշանը, որոշ վազանցները, կանգառը կամ սահմանված արագությունից բարձր երթևեկությունը։ Նկարի նշանները՝ [[3.26]], [[2.4]], [[3.20]], [[3.27]], [[3.24]]։",
    43: "Մեխանիկական տրանսպորտային միջոցի վրա բութակավոր դողերի առկայությունը նշվում է համապատասխան ճանաչման նշանով։ Այն տեղեկացնում է մեքենայի սարքավորման մասին և ինքնուրույն երթևեկության արգելք չի սահմանում։ Նկարում՝ [[tsr-9.5]]։",
    44: "Միակողմ երթևեկությամբ ճանապարհի վերջը ցույց է տալիս 4-րդ կապույտ նշանը՝ կարմիր շեղ գծով։ Այն զգուշացնում է, որ միակողմ երթևեկության ռեժիմն ավարտվում է, և վարորդը պետք է պատրաստ լինի հանդիպակաց հոսքին։ Նկարի նշանները՝ [[5.5]], [[5.6]], [[5.5]], [[5.6]], [[5.15.1]]։",
    45: "Հատվող ճանապարհի մասնակիցներին զիջելու պահանջը ներկայացված է շրջված եռանկյունով «Զիջեք ճանապարհը» նշանով։ Դրա պահանջը կատարվում է՝ առաջնահերթություն ունեցողներին ճանապարհ տալով, իսկ ոչ թե պարզապես դանդաղեցնելով՝ առանց իրավիճակը գնահատելու։ Նկարում՝ [[2.4]]։",
    46: "Կապույտ P-ն ցույց է տալիս կայանման տեղը, ստորին նշանը սահմանափակում է այն հաշմանդամության նշանով կահավորված մեքենաների և մոտոսայլակների համար, իսկ վերև-ներքև սլաքներով ցուցանակը ցույց է տալիս 30 մ երկարությունը։ Հետևաբար սա սովորական ընդհանուր կայանատեղի չէ։ Նկարում՝ [[6.4]], [[tsr-9.13]], [[8.2.1]]։",
    47: "Տրանսպորտային միջոցի ճանաչման նշան է 3-րդ քառակուսի դեղին նշանը, որի վրա պատկերված են երեխաներ։ Եռանկյունը նախազգուշացնում է երեխաների հնարավոր ներկայության մասին, իսկ կապույտ շրջանը հետիոտնային արահետ է ցույց տալիս։ Նկարի նշանները՝ [[1.23]], [[4.5]], [[tsr-9.4]]։",
    48: "Կարմիր եզրագծով շրջանի մեջ մարդատար մեքենայի պատկերով նշանն արգելում է մեխանիկական տրանսպորտային միջոցների երթևեկությունը։ Այն չի արգելում բոլոր հնարավոր տեսակի տրանսպորտային միջոցների շարժը՝ անկախ դրանց մեխանիկական լինելուց։ Նկարում՝ [[3.3]]։",
    49: "Արգելքի երկու կողմից շրջանցման թույլտվությունը ցույց է տալիս կապույտ շրջանաձև նշանը՝ ձախ և աջ ուղղված սլաքներով։ Այն վարորդին թույլ է տալիս ընտրել անվտանգ կողմը՝ չանցնելով հանդիպակաց հոսքի գոտի, եթե այդպիսի մանևրն արգելված է։ Նկարում՝ [[4.2.3]]։",
    50: "Կազմակերպված խմբով երեխաներ տեղափոխող տրանսպորտային միջոցի առջևում և հետևում տեղադրվում է երեխաների փոխադրման ճանաչման նշանը։ Նկարի 1-ին դեղին քառակուսին համապատասխանում է այդ նշանին, իսկ մյուս պատկերները երեխաների տեղաշարժի կամ հետիոտնային գոտու մասին են։ Նկարի նշանները՝ [[tsr-9.4]], [[tsr-9.13]], [[4.5]], [[1.23]]։",
    51: "Գլխավոր ճանապարհի ուղղությունը փոխվում է խաչմերուկում, և լրացուցիչ սխեման ցույց է տալիս, որ այն շարունակվում է դեպի ձախ։ Ուստի վարորդը պետք է առաջնորդվի առաջնահերթ ճանապարհի ընթացքով, ոչ միայն ճանապարհի տեսանելի ուղիղ հատվածով։ Նկարում՝ [[2.1]], [[8.13]]։",
    52: "50 նշումով քառակուսի ցուցանակը առաջարկվող արագություն է, ոչ թե պարտադիր առավելագույն կամ նվազագույն սահման։ Լրացուցիչ 800 մ ցուցանակը սահմանում է այդ առաջարկության կիրառման հատվածը, ուստի այդ գոտում վարորդին առաջարկվում է պահպանել 50 կմ/ժ-ը։ Նկարում՝ [[6.2]], [[8.2.1]]։",
    53: "Խոնավ ճանապարհածածկույթի դեպքում գործում է միայն C համադրությունը․ 50 կմ/ժ առավելագույն արագության նշանի տակ անձրևի պատկերով ցուցանակը արագության պահանջը կապում է թաց ծածկույթի հետ։ Սայթաքուն ճանապարհի կամ խճի արտանետման նախազգուշացումները ինքնին խոնավությունից կախված արագության սահմանափակում չեն։ Նկարի նշանները՝ [[1.15]], [[1.18]], [[3.24]], [[8.16]]։",
    54: "Նկարում հանդիպակաց երթևեկության ուղղությունների և գոտիների վերադասավորման սխեման ցույց է տալիս, որ վարորդը պետք է անցնի հանդիպակաց երթևեկելի մաս։ Դա պետք է կատարել միայն նշանի ցուցումով և համոզվելով, որ ճանապարհը ազատ է․ հակառակ հոսքի հետ բախման վտանգը առաջնային է։ Նկարում՝ [[5.8]]։",
    55: "Ճանապարհի նեղացման նշանը նախազգուշացնում է, որ 150–300 մ հետո աջ կողմից ճանապարհը կնեղանա։ Հեռավորության ցուցանակը տալիս է մինչև վտանգավոր հատվածը մնացած ճանապարհը, իսկ 100 մ ցուցանակը՝ հենց նեղ հատվածի երկարությունը։ Նկարում՝ [[1.20.2]], [[8.1.1]], [[8.2.1]]։",
    56: "Ցուցանակի երկու հակառակ ուղղված սլաքները ցույց են տալիս, որ նշանի ազդեցության հատվածը տարածվում է երկու ուղղությամբ։ Այդ պատճառով երթևեկությունը թույլատրվում է ուղիղ և հակառակ ուղղությամբ՝ պահպանելով այդ հատվածի սահմանափակման պայմանները։ Նկարում՝ [[3.2]], [[8.2.4]]։",
    57: "Կապույտ շրջանի կարմիր X-ը կանգառն արգելող նշանն է, իսկ աստղիկով ցուցանակը ցույց է տալիս, որ արգելքը գործում է հանգստյան և տոն օրերին։ Ուստի արգելքը մշտական չէ․ այն կախված է շաբաթվա և տոնական օրերի կարգավիճակից։ Նկարում՝ [[3.27]], [[8.5.3]]։",
    58: "Հետադարձն արգելող նշանը 3-րդն է՝ կարմիր շրջան, որի ներսում սլաքը կտրուկ շրջվում է հետ։ Ձախ կամ աջ շրջադարձ արգելող նշանները չեն արգելում հետադարձը, եթե առանձին արգելք չկա։ Նկարի նշանները՝ [[3.18.1]], [[3.18.2]], [[3.19]]։",
    59: "Ճանապարհային աշխատանքների նշանն ու մեքենայի պատկերով լրացուցիչ ցուցանակը միասին զգուշացնում են, որ նորոգման պատճառով կողնակ դուրս գալը վտանգավոր է։ Վարորդը պետք է պահպանի իր գոտին և խուսափի կողնակի փափուկ կամ չամրացված հատվածից։ Նկարում՝ [[1.25]], [[8.12]]։",
    60: "«Կանգառն առանց կանգառի արգելվում է» նշանը պահանջում է ամբողջական կանգ առնել նշանի կամ կանգ-գծի առաջ, ապա զիջել հատվող ճանապարհով ընթացողներին։ Դանդաղեցնելն առանց անիվների լրիվ կանգի բավարար չէ։ Նկարում՝ [[2.5]]։",
    61: "Նկարի 4-րդ նշանը սահմանում է մեխանիկական տրանսպորտային միջոցների երթևեկության արգելք, սակայն ընդհանուր օգտագործման տրանսպորտային միջոցների վրա այդ արգելքը չի տարածվում՝ նշված բացառության համաձայն։ Մյուս պատկերները վերաբերում են կայանման կամ կանգառի սահմանափակումներին և նույն բացառությունը չունեն։ Նկարի նշանները՝ [[3.28]], [[3.29]], [[3.27]], [[3.3]]։",
    62: "Հատվող ճանապարհի վրա երկկողմ սլաքով կապույտ նշանը տեղեկացնում է, որ այնտեղ կազմակերպված է դարձափոխային երթևեկություն։ Գոտիների ուղղությունները կարող են փոխվել ըստ կառավարման ռեժիմի, ուստի պետք է հետևել գոտու վերևի ազդանշաններին։ Նկարում՝ [[5.8]]։",
    63: "Բեռնատարին պետք է զիջել, քանի որ տվյալ իրավիճակում նշանով տրված առավելությունը նրանն է։ Վարորդը չի կարող միայն իր դիրքով կամ շարժման ուղղությամբ եզրակացնել, որ ինքն է առաջնահերթ․ պետք է հաշվի առնել նաև դարձափոխային երթևեկության նշանը։ Նկարում՝ [[5.8]]։",
    64: "40 կմ/ժ առավելագույն արագության նշանի տակ անձրևի պատկերով ցուցանակը սահմանափակումը կապում է խոնավ ճանապարհածածկույթի հետ։ Թաց ճանապարհին 40-ից արագ գնալ չի կարելի, իսկ չոր ճանապարհին այդ լրացուցիչ պայմանը չի գործում։ Նկարում՝ [[3.24]], [[8.16]]։",
    65: "Կապույտ X-աձև նշանը կանգառն արգելում է, իսկ խաչված մուրճերի պատկերով ցուցանակը սահմանափակումն ուժի մեջ է դնում աշխատանքային օրերին։ Այդ օրերին կանգառ կատարել չի կարելի, անկախ նրանից՝ մեքենան կարճ ժամանակով է կանգնելու, թե երկար։ Նկարում՝ [[3.27]], [[8.5.2]]։",
    66: "Նկարի նախազգուշացնող նշանը հայտնում է կողային քամու վտանգի մասին, իսկ 50 կմ/ժ կապույտ նշանը տվյալ հատվածում առաջարկվող արագությունն է։ Սա արագության պարտադիր առավելագույն սահման չէ, բայց քամու պայմաններում նշված արագությունը անվտանգ ուղենիշ է։ Նկարում՝ [[1.29]], [[6.2]]։",
    67: "Երրորդ կապույտ շրջանաձև նշանը երկու սլաքով պարտադրում է երթևեկել միայն ձախ կամ աջ։ Այն ուղիղ շարժում չի թույլատրում, ի տարբերություն առաջին երկու նշանների, որոնցում ուղիղ սլաք կա։ Նկարում՝ [[4.1.6]]։",
    68: "40 կմ/ժ արագության կապույտ ցուցանակը առաջարկություն է, իսկ անձրևի պատկերով ցուցանակը ցույց է տալիս, որ այն վերաբերում է թաց ծածկույթին։ Հետևաբար թաց ճանապարհին խորհուրդ է տրվում երթևեկել 40 կմ/ժ արագությամբ, սակայն դա պարտադիր առավելագույն սահման չէ։ Նկարում՝ [[6.2]], [[8.16]]։",
    69: "Կայանման կամ կանգառի արգելքի ազդեցությունը ճանապարհի այն կողմում է, որտեղ նշանը տեղադրված է։ Նշանի դիրքն ու լրացուցիչ գծանշումները չեն տարածում արգելքը փողոցի հակառակ կողմի վրա։ Նկարում՝ [[3.28]], [[3.29]]։",
    70: "Խցանման պատճառով խաչմերուկ մտնել չի կարելի, եթե կանգնելով կփակեք հատող հոսքը։ Գործող 88-րդ կետի բացառությունը վերաբերում է աջ կամ ձախ շրջադարձին. պատասխանի «հետադարձը» բացառության մեջ հստակ ներառված չէ, ուստի պատասխանի բանալին պետք է վերանայել։",
    71: "Կանգառի ու երկաթուղային գծանցի նշանների համադրության դեպքում կանգ առնելը պահանջվում է երկրորդ նշանի առաջ՝ գծանցին հնարավորինս մոտ, բայց անվտանգ հեռավորությամբ։ Առաջին նշանը միայն նախազգուշացնում է, իսկ «Կանգառն առանց կանգառի արգելվում է» նշանն է պարտադիր կանգառ սահմանում։ Նկարում՝ [[2.5]], [[1.3.2]]։",
    72: "Աջ շրջադարձի ժամանակ պետք է ընտրել աջ շրջադարձի համար նախատեսված գոտին և կատարել մանևրը անվտանգ ձևով։ Եթե գոտիների ուղղությունները ցույց են տրված նշանով, հետևում ենք այդ նշանին, իսկ շրջադարձից առաջ դիրքավորվելիս՝ նաև գծանշմանը․ երկու նշված գործողություններն էլ անհրաժեշտ են։ Նկարում՝ [[5.15.1]], [[5.14]]։",
    73: "Հետադարձի տեղը ցույց տվող նշանից առաջ դրված 200 մ ցուցանակը հայտնում է, որ հետադարձի հնարավորությունը նշանից հեռու է, ոչ թե արգելում է այն։ Վարորդը կարող է շարունակել մինչև նշված տեղը և այնտեղ հետադարձ կատարել՝ եթե մանևրն անվտանգ է։ Նկարում՝ [[6.3.1]], [[8.1.1]]։",
    74: "Կարգավորողի ձեռքով տրված կանգառի ազդանշանը պարտադիր է, նույնիսկ եթե ճանապարհի եզրին կանգառն արգելող նշան կա։ Կարգավորողի ազդանշանն ավելի բարձր ուժ ունի, և վարորդը պետք է կանգնի նրա ցույց տված տեղում։ Նկարում՝ [[3.27]]։",
    75: "Բազմագիծ երկաթուղային գծանցի առաջ տեղադրված կանգառի նշանը պահանջում է կանգնել, համոզվել, որ բոլոր գծերը ազատ են, և միայն հետո անցնել։ Շոգեքարշի նշանը կամ մոտեցման շերտերը պարզապես չեն փոխարինում կանգառի այդ պահանջին։ Նկարի նշանները՝ [[1.3.2]], [[2.5]], [[1.4.4]]։",
    76: "Գծանշված գոտու երկու եզրերը ցույց են տալիս դարձափոխային երթևեկության գոտու սահմանները։ Նման գոտում երթևեկության ուղղությունը փոփոխական է, և սովորական հոծ գծի պես այն հատել չի կարելի՝ առանց ազդանշանների ու նշանների թույլտվության։",
    77: "Թեթև մարդատարի երթևեկությունը որոշվում է խաչմերուկում գոտիների սլաքներով․ մեքենան կարող է շարունակել ուղիղ, թեքվել ձախ կամ կատարել հետադարձ միայն թույլատրող գոտուց։ Մանևրից առաջ պետք է դիրքավորվել համապատասխան գոտում և զիջել հետիոտներին։ Նկարում՝ [[5.15.1]]։",
    78: "4.3 նշանով կահավորված շրջանաձև երթևեկության խաչմերուկ մուտք գործելիս վարորդը պարտավոր է զիջել այնտեղ արդեն ընթացողներին։ Այս հարցը մեկնաբանված է միայն տեքստի հիման վրա։ Կանոն՝ 98.1։ Նշանը՝ [[4.3]]։",
    79: "Բնակավայրից դուրս նախազգուշացնող նշանը սովորաբար տեղադրվում է վտանգավոր հատվածից 150–300 մ առաջ։ Այդ հեռավորությունը ժամանակ է տալիս արագությունը հարմարեցնելու և վտանգավոր ոլորաններին պատրաստվելու համար։ Նկարում՝ [[1.12.1]]։",
    80: "Միակողմ երթևեկության նշանը ցույց է տալիս ճանապարհի ուղղությունը, իսկ խաչմերուկի գոտիների սլաքները թույլ են տալիս տվյալ կետում շարունակել ուղիղ, աջ կամ ձախ։ Պետք է տարբերել ճանապարհի միակողմ ռեժիմը խաչմերուկում թույլատրվող մանևրներից։ Նկարում՝ [[5.5]], [[5.15.1]]։",
    81: "Խաչմերուկում դեղին ցանցագծված հատվածը ցույց տվող 3-րդ պատկերը նշանակում է, որ չի կարելի մտնել այդ հատված, եթե խցանման պատճառով ստիպված կլինեք կանգնել դրա մեջ։ Արգելքը չի վերաբերում աջ կամ ձախ շրջադարձ կատարողներին՝ ըստ կանոնի։",
    82: "«Խցանում» նշանի տեսակը զգուշացնում է խաչմերուկի այն հատվածի մասին, որտեղ խցանման դեպքում մուտք գործել չի կարելի։ Բարդ խաչմերուկներում այն կարող է տեղադրվել խաչմերուկի սահմաններից առաջ՝ առավելագույնը 30 մ հեռավորության վրա։ Նկարում՝ [[1.32]]։",
    83: "Նշանը տեղեկացնում է խցանման պատճառով խաչմերուկի տարածք մուտք գործելու արգելքի մասին։ Եթե խաչմերուկում կանգնելու եք և փակելու եք երթևեկությունը, պետք է սպասել մինչև ձեր ուղղությամբ անցնելու բավարար տեղ բացվի։ Նկարում՝ [[1.32]]։",
    84: "Դեղին ցանցագծված գծանշումը սահմանազատում է խաչմերուկի այն հատվածը, որտեղ խցանման պատճառով կանգնելն ու երթևեկությունը փակելը արգելված է։ Այն «Խցանում» նշանի իմաստն արտահայտում է արդեն ճանապարհածածկույթի վրա։",
    85: "Ցանցաձև դեղին գծանշումով 3-րդ տարբերակն է ցույց տալիս խաչմերուկի հատվածը, որտեղ խցանման պատճառով կանգնել չի կարելի։ Մյուս երկու գծանշումները այլ նպատակ ունեն, ուստի միայն ցանցի պատկերն է համապատասխանում նկարագրությանը։",
    86: "Գոտիների վերևում տեղադրված սլաքները ցույց են տալիս յուրաքանչյուր գոտուց թույլատրված շարժման ուղղությունները։ Հետադարձը տվյալ գոտուց արգելված է, եթե այդ գոտու սլաքը հետադարձ չի թույլատրում․ վերադասավորվել պետք է դեռ մինչև խաչմերուկ հասնելը։ Նկարում՝ [[5.15.1]]։",
    87: "Կապույտ պարտադիր ուղղության նշանը կարգադրում է շարունակել ուղիղ։ A հետագիծն է համապատասխանում այդ պահանջին․ B-ն շեղվում է և հակասում է նշանի սլաքին։ Նկարում՝ [[4.1.1]]։",
    88: "Նկարում նեղացման և գոտու ուղղության պայմանները չեն թողնում նշված հետագծերից որևէ մեկով հետադարձ կատարել։ Հետադարձն արգելվում է, եթե դրա համար պետք է հատել բաժանարար գիծը կամ շարժվել նշանի ու գծանշման հակառակ ուղղությամբ։ Նկարում՝ [[1.20.2]], [[5.15.1]]։",
    89: "Կապույտ պարտադիր աջ ուղղության նշանը չի թույլատրում ուղիղ շարունակել։ Նշված իրավիճակում ուղիղ կարող է անցնել միայն ընդհանուր օգտագործման տրանսպորտային միջոցը, եթե այն շարժվում է իր համար առանձնացված գոտով և նշանը տարածվում է մյուս գոտիների վրա։ Նկարում՝ [[4.1.2]]։",
    90: "Խաչմերուկում A հետագիծն է համապատասխանում թույլատրված հետադարձի ձևին։ Մանևրը պետք է կատարել խաչմերուկի սահմաններում՝ առանց հակառակ հոսքի գոտի դուրս գալու կամ այլ ճանապարհային մասնակիցների ընթացքը կտրելու։ Նկարում՝ [[4.1.2]]։",
    91: "Այս իրավիճակում կանաչ լուսացույցը թույլատրում է անցնել, իսկ կանգ-գիծը միայն սահմանում է կանգնելու տեղը, երբ կանգառ է պահանջվում։ Կանգառի անհրաժեշտություն չկա, քանի դեռ լուսացույցի ազդանշանը թույլատրում է շարժումը և կարգավորողը այլ հրահանգ չի տալիս։ Նկարում՝ [[6.16]]։",
    92: "Կապույտ շրջանաձև սլաքները ցույց են տալիս, որ թույլատրվում է շարժվել միայն նշված ուղղություններով։ Նշված A և B հետագծերն են համապատասխանում սլաքներին․ մյուս ուղղությունը նշանով արգելված է։ Նկարում՝ [[4.1.6]]։",
    93: "Կանաչ պատկերանշանը ցույց է տալիս վթարային ելքի ուղղությունը և մինչև ելքը մնացած հեռավորությունը։ Այն տեղեկատվական նշան է թունելում, ոչ թե սովորական ելք կամ սպասարկման կետ։ Նկարում՝ [[6.20.1]]։",
    94: "Նեղ հատվածում վարորդին առավելություն տվող նշանը թույլ է տալիս առաջինն անցնել, իսկ հանդիպակաց կողմը պետք է սպասի։ Նկարում ձեր ուղղության նշանն է տալիս այդ առավելությունը, հետևաբար կարող եք անցնել առաջինը՝ համոզվելով, որ հակառակ ուղղությամբ մեքենան արդեն կանգնել է։ Նկարում՝ [[2.7]]։",
    95: "80 կմ/ժ առավելագույն արագության նշանը սահմանում է ընդհանուր սահմանը, իսկ մեքենայի պատկերով լրացուցիչ նշանը նշում է, թե որ տրանսպորտային միջոցների վրա է տարածվում համապատասխան կարգավորումը։ 3.5 տոննայից ոչ ավելի թույլատրելի զանգվածով բեռնատարի համար այստեղ առավելագույնը 80 կմ/ժ է։ Նկարում՝ [[3.24]], [[8.4.3]]։",
    96: "«Հետիոտնային գոտի» նշանի ազդեցության տակ արգելվում է բոլոր տրանսպորտային միջոցների երթևեկությունը, եթե կանոններով նախատեսված բացառություն կամ թույլտվություն չկա։ Նկարում հենց «Գոտի» գրությամբ և հետիոտնի պատկերով նշանն է։ Նկարում՝ [[5.33]]։",
    97: "«Կանգառն առանց կանգառի արգելվում է» պահանջը կատարելու համար կանգնում են հատվող երթևեկելի մասի առաջ, նշված C կետում։ A կամ B կետերում կանգնելը դեռ կարող է լինել խաչմերուկի գոտում կամ խանգարել մյուսներին։ Նկարում՝ [[2.5]]։",
    98: "Արագության պարտադիր սահմանափակում է սահմանում միայն կարմիր եզրագծով 50 նշանը՝ 2-րդ տարբերակը։ Կապույտ քառակուսի 50-ը առաջարկվող արագություն է, իսկ եռանկյուն նշանը նախազգուշացնում է խճի արտանետման մասին։ Նկարի նշանները՝ [[2.4]], [[5.21]], [[3.24]], [[1.18]]։",
    99: "A նշանի տակ գտնվող սլաքը ցույց է տալիս, որ արագության պահանջը վերաբերում է հենց այն գոտուն, որի վերևում նշանը տեղադրված է։ B-ն նվազագույն արագություն է սահմանում, իսկ C-ն առաջարկվող արագություն է ցույց տալիս, բայց դրանք այդ կերպ գոտի չեն սահմանազատում։ Նկարի նշանները՝ [[3.24]], [[8.14]], [[4.6]], [[6.2]]։",
    100: "Կայանել կարելի է, քանի որ մեքենան գտնվում է արգելքի գոտու մեկնարկային նշանից առաջ։ «Կայանելն արգելվում է» նշանը գործում է դրա տեղադրման վայրից հետո, իսկ լրացուցիչ սլաքները հստակեցնում են գոտու սահմանները։ Նկարում՝ [[3.28]], [[8.2.2]]։",
    101: "Կայանման նշանի տակ բեռնատարի պատկերով ցուցանակը սահմանափակում է կայանման վայրը նշված տրանսպորտային միջոցների համար։ Բեռնատարի վարորդը խախտել է կանոնը, քանի որ կայանել է այդ նշանի ազդեցության տակ՝ իրեն չվերաբերող տեղում։ Նկարում՝ [[6.4]], [[8.4.1]]։",
    102: "Աջ շրջադարձն արգելող նշանը չի արգելում ուղիղ երթևեկել կամ հետադարձ կատարել, եթե խաչմերուկի այլ նշաններ դա չեն արգելում։ Հետևաբար թույլատրվում են ուղիղ և հակառակ ուղղությունները, բայց ոչ աջ շրջադարձը։ Նկարում՝ [[3.18.1]]։",
    103: "Բնակիչների համար նախատեսված բացառությունը վերաբերում է նշված գոտու ներսում գտնվող հասցեներին սպասարկող մեքենաներին։ A և C արգելքների դեպքում բնակության վայր հասնելու բացառությունը գործում է, իսկ մյուս նշանի ազդեցությունը մնում է ուժի մեջ։ Նկարի նշանները՝ [[3.1]], [[3.2]], [[3.3]]։",
    104: "Ցուցանակի վրա «Կանգառն առանց կանգառի արգելվում է» նշանի գրությունը և 250 մ հեռավորությունը տեղեկացնում են, որ հիմնական STOP նշանը տեղադրված է 250 մ առաջ։ Ցուցանակը նախապես զգուշացնում է կանգառի պահանջի մասին, բայց ինքնուրույն կանգառ չի պարտադրում։ Նկարում՝ [[2.4]], [[2.5]], [[8.1.1]]։",
    105: "Նշանը արգելում է կանգառը այն հատվածում, որը գտնվում է դրա ազդեցության տակ։ Նշված մեքենան դեռ գտնվում է արգելքի մեկնարկից առաջ, ուստի ուղևոր նստեցնելու կարճ կանգառը թույլատրվում է՝ եթե այն վտանգ կամ խոչընդոտ չի ստեղծում։ Նկարում՝ [[3.27]]։",
    106: "B և D նշաններն են, որոնց ազդեցությունը տարածվում է մինչև մոտակա խաչմերուկը, եթե ավելի շուտ ավարտի այլ նշան չի տեղադրվել։ Մյուս սահմանափակումները գործում են նշված գոտու կամ տրանսպորտային միջոցների տեսակների նկատմամբ։ Նկարի նշանները՝ [[5.31]], [[3.24]], [[5.27]], [[3.28]]։",
    107: "Ձախ գոտու վրա տեղադրված նվազագույն արագության նշանը պահանջում է այդ գոտում երթևեկել առնվազն 50 կմ/ժ արագությամբ։ Այն առավելագույն արագության նշան չէ, հետևաբար 50-ից արագ ընթացքը թույլատրելի է՝ ընդհանուր սահմանափակումների սահմաններում։ Նկարում՝ [[4.6]], [[8.14]]։",
    108: "A և C նշաններն են, որոնց ուղղության կարգավորումը բացառում է ձախ շրջադարձը․ վարորդը պետք է հետևի նշված սլաքներին և տվյալ գոտու թույլատրված ուղղություններին։ Միայն հետադարձն արգելող նշանը ձախ շրջադարձի արգելք չի նշանակում։ Նկարի նշանները՝ [[5.15.1]], [[3.19]], [[6.3.1]]։",
    109: "Ձախ շրջադարձը թույլատրվում է, քանի որ նշանը ցույց է տալիս փակուղի կամ ուղղության տեղեկություն, բայց չի պարունակում ձախ շրջադարձի արգելք։ Մանևրից առաջ պետք է զիջել առաջնահերթություն ունեցողներին և ստուգել՝ շրջադարձը չի հակասում գծանշմանը։ Նկարում՝ [[6.8.1]]։",
    110: "Եռանկյուն նշանը զգուշացնում է հետիոտնային անցման մասին, իսկ 150 մ ցուցանակը ցույց է տալիս մինչև այն եղած հեռավորությունը։ Սա չկարգավորվող անցում է, ուստի վարորդը պետք է նախապես իջեցնի արագությունը և պատրաստ լինի զիջելու հետիոտնին։ Նկարում՝ [[1.22]], [[8.1.1]]։",
    111: "Շրջանաձև երթևեկության նշանը պահանջում է հանգույց մտնելիս շարժվել շրջանաձև ուղղությամբ և պահպանել առաջնահերթության կանոնը։ Նկարում միայն B հետագիծն է համապատասխանում շրջանաձև երթևեկության ճիշտ շարունակությանը։ Նկարում՝ [[4.3]]։",
    112: "A և B նշանները սահմանում են հատուկ ճանապարհային ռեժիմներ, որոնց ներքո 40 կմ/ժ-ից պակաս արագությամբ երթևեկելն արգելված է տվյալ պայմաններում։ Կապույտ քառակուսի 50-ը առաջարկվող արագություն է, իսկ կանաչ նշանը ցույց է տալիս ավտոմայրուղի։ Նկարի նշանները՝ [[5.1]], [[5.3]], [[6.2]]։",
    113: "Նեղ հատվածում հանդիպակաց երթևեկողին զիջելու պահանջը սահմանում են A և C նշանները՝ համապատասխան առաջնահերթության պատկերներով։ Դրանք պետք է տարբերել նեղ ճանապարհի նախազգուշացումից, որը միայն տեղեկացնում է վտանգի մասին, բայց ինքնուրույն չի որոշում՝ ով է առաջինը անցնում։ Նկարի նշանները՝ [[2.6]], [[2.7]], [[2.4]], [[2.6]]։",
    114: "3.5 տոննա թույլատրելի առավելագույն զանգված ունեցող բեռնատարի վարորդը կարող է շարունակել ցանկացած ուղղությամբ, քանի որ բեռնատարների երթևեկության արգելքի սահմանը վերաբերում է 3.5 տոննայից ավելի զանգված ունեցողներին։ Ճանապարհի ուղղության մյուս նշանները խաչմերուկում չեն սահմանափակում այս մեքենայի շարժումը։ Նկարում՝ [[3.4]], [[6.15.1]]։",
    115: "Աջ շրջադարձ դեպի հողային ճանապարհ թույլատրվում է, քանի որ վտանգավոր ձախ ոլորանի նախազգուշացնող նշանը միայն զգուշացնում է ճանապարհի ձևի մասին։ Այն չի արգելում կողմնակի ճանապարհ մտնելը․ պետք է միայն համոզվել, որ շրջադարձն անվտանգ է։ Նկարում՝ [[1.11.2]]։",
    116: "Կանգառն արգելող նշանի տակ 50 մ հեռավորության ցուցանակը ցույց է տալիս, որ սահմանափակումը սկսվում է նշանից 50 մ հետո։ Մինչև այդ սահմանը ուղևոր նստեցնելու համար կանգառը թույլատրվում է, եթե մեքենան չի խանգարում երթևեկությանը։ Նկարում՝ [[3.28]], [[8.1.1]]։",
    117: "B կապույտ շրջանաձև նշանը հետիոտնային արահետ է ցույց տալիս և պարտադրում է հետիոտների երթևեկության համար նախատեսված ուղին։ A-ն արգելում է հետիոտնի տեղաշարժը, իսկ C-ն նշում է հետիոտնային անցումը։ Նկարի նշանները՝ [[3.10]], [[4.5]], [[5.19.1]]։",
    118: "Կապույտ շրջանի մեջ հակառակ ուղղված սլաքներով առաջնահերթության նշանը պահանջում է հանդիպակաց մեքենային զիջել նեղ հատվածում։ Հանդիպակացը կարող է անցնել առաջինը, և դուք պետք է սպասեք մինչև ճանապարհը ազատվի։ Նկարում՝ [[2.6]]։",
    119: "Միակողմ երթևեկությամբ ճանապարհի նշանը թույլ է տալիս շարունակել միայն սլաքի ուղղությամբ։ Եթե պետք է փոխել ընթացքը հակառակ ուղղությամբ, խաչմերուկը նախ ուղիղ անցնելուց հետո ընտրեք թույլատրելի տեղ՝ հետադարձ կատարելու համար։ Նկարում՝ [[5.5]]։",
    120: "Հետադարձի տեղը և կանգառի արգելքը միասին չեն թույլատրում մեքենան կանգնեցնել նշված հատվածում։ Հետադարձի ցուցանակը վերաբերում է մանևրի տեղին, իսկ կանգառն արգելող նշանը շարունակում է գործել իր սահմանած գոտում։ Նկարում՝ [[6.3.1]], [[3.27]]։",
    121: "Մեքենայի պատկերով լրացուցիչ ցուցանակը նշում է, որ իր հետ կիրառվող սահմանափակումը վերաբերում է թեթև մարդատարներին և մինչև 3.5 տոննա թույլատրելի առավելագույն զանգված ունեցող բեռնատարներին։ Ավելի ծանր բեռնատարների համար այդ բացառությունը կամ սահմանումը չի գործում նույն կերպ։ Նկարում՝ [[8.4.3]]։",
    122: "Ճանապարհային աշխատանքների եռանկյուն նշանը զգուշացնում է նորոգման մասին, իսկ մեքենայի պատկերով ցուցանակը ցույց է տալիս, որ կողնակ դուրս գալը վտանգավոր է։ Վարորդը պետք է երթևեկի զգուշորեն և չմտնի փափուկ կամ չամրացված կողնակ։ Նկարում՝ [[1.25]], [[8.12]]։",
    123: "Վերգետնյա գոտիների ուղղության նշանները յուրաքանչյուր գոտու համար առանձին ցույց են տալիս թույլատրված շարժումը։ Պետք է նախապես ընտրել այն գոտին, որի սլաքը համապատասխանում է անհրաժեշտ ուղղությանը․ գծանշման հոծ հատվածը հատել չի կարելի։ Նկարում՝ [[5.15.1]]։",
    124: "Խաչմերուկում պարտադիր ուղիղ երթևեկության նշանը թույլ չի տալիս թեքվել դեպի այն ուղղությունը, որը հակասում է սլաքին։ Նկարում նշված A և B հետագծերն են համապատասխանում նշանի պահանջին ու ճանապարհային գծանշմանը։ Նկարում՝ [[4.1.1]]։",
    125: "Կարմիր եզրագծով 40 նշանը սահմանում է առավելագույն արագությունը՝ 40 կմ/ժ։ Նշանի ազդեցության գոտում այդ արժեքից արագ ընթանալ չի կարելի, իսկ ճանապարհային պայմանների դեպքում պետք է ընտրել ավելի ցածր անվտանգ արագություն։ Նկարում՝ [[3.24]]։",
    126: "B և C ցուցանակները ցույց են տալիս իրենց հետ կիրառվող նշանի ազդեցության գոտու երկարությունը կամ սահմանները։ A-ի 300 մ-ը մինչև նշված տեղը մնացած հեռավորությունն է, մինչդեռ սլաքներով ցուցանակները սահմանում են հատվածը, որի վրա հիմնական նշանի պահանջը գործում է։ Նկարի ցուցանակները՝ [[8.1.1]], [[8.2.1]], [[8.2.2]]։",
    127: "Ուղիղ երթևեկության պարտադիր նշանը կարգավորում է շարժումը խաչմերուկում, բայց չի արգելում աջ կողմում գտնվող մերձակա տարածքի մուտքը, երբ այն խաչմերուկի աջ շրջադարձ չէ և կանոններով թույլատրվում է։ Այդ պատճառով կարելի է մտնել աջ բակ՝ համոզվելով, որ հետիոտներին ու հեծանվորդներին չեք խանգարում։ Նկարում՝ [[4.1.1]]։",
    128: "A և B նշանները սկսում են գործել անմիջապես տեղադրման վայրից, քանի որ դրանց տակ չկա հեռավորությունը ցույց տվող լրացուցիչ ցուցանակ։ C-ի 200 մ ցուցանակը հայտնում է, որ սահմանափակումը կսկսվի ավելի ուշ։ Նկարի նշանները՝ [[3.24]], [[8.1.1]], [[3.24]], [[8.1.1]]։",
    129: "Հետադարձի համար նախատեսված տեղում A հետագիծն է թույլատրելի, իսկ B-ն հակասում է ճանապարհի կազմակերպմանը։ Մանևրն ավարտելիս անհրաժեշտ է պահպանել բաժանարար գծերը և չխանգարել մյուս ուղղություններով երթևեկողներին։ Նկարում՝ [[6.3.1]]։",
    130: "Քարերի կամ խճի պատկերով նախազգուշացնող նշանը հայտնում է, որ մեքենաների անիվներից կարող է խիճ ցայտել և վնասել ձեր մեքենան կամ ապակիները։ Պետք է նվազեցնել արագությունը և մեծացնել հետևող մեքենաների հետ հեռավորությունը։ Նկարում՝ [[1.18]]։",
    131: "Բնակավայրի երթևեկության կարգը սկսվում է այն նշանից հետո, որը բնակավայրը ցույց է տալիս սպիտակ հիմնագույնով։ Կապույտ հիմնագույնով քաղաքային նշանը հիմնականում տեղեկացնում է բնակավայրի անվան մասին, բայց չի սահմանում բնակավայրի արագության ռեժիմը։ Նկարի նշանները՝ [[5.23.1]], [[5.23.2]], [[5.25]]։",
    132: "Լրացուցիչ ցուցանակը ցույց է տալիս, որ ուղիղ երթևեկության պարտադիր պահանջը վերաբերում է նշված տեսակի բեռնատարներին, ոչ թե թեթև մարդատարին։ Ուստի մարդատարի վարորդը կարող է ընտրել խաչմերուկում իրեն թույլատրված ցանկացած ուղղություն՝ պահպանելով մյուս նշանները։ Նկարում՝ [[4.1.1]], [[8.4.1]]։",
    133: "«Կայանելն արգելվում է» նշանը չի արգելում բեռնաթափման համար կանգառը, եթե տրանսպորտային միջոցը բեռնաթափում է և չի խախտում կանգառն արգելող այլ պահանջ։ Այդ պատճառով բեռնաթափման տևողությունն ինքնին թույլտվությունը չի վերացնում։ Նկարում՝ [[3.28]]։",
    134: "Նկարի տարբերակներից ոչ մեկը հետադարձի արգելք չի սահմանում։ Ձախ կամ աջ շրջադարձ արգելող նշանները սահմանափակում են միայն համապատասխան շրջադարձը, իսկ ուղղության ցուցիչը ցույց է տալիս շարժման կազմակերպումը։ Նկարի նշանները՝ [[4.1.3]], [[3.18.2]], [[6.10.2]]։",
    135: "Մուտքը թույլատրվում է, քանի որ տվյալ խաչմերուկի պարտադիր ուղիղ նշանը չի արգելում աջ կողմի բակ կամ հարակից տարածք մտնելը։ Այդ մուտքը չպետք է դիտվի որպես արգելված խաչմերուկային շրջադարձ և պետք է կատարվի հետիոտներին զիջելով։ Նկարում՝ [[4.1.1]]։",
    136: "Կանգառն արգելող նշանի ազդեցության տակ ուղևոր նստեցնելու համար կանգ առնել չի կարելի, քանի որ ուղևորի նստեցումը նույնպես կանգառ է։ Ցուցանակը ցույց է տալիս արգելքի սահմանը, և երկու ներկայացված դիրքերն էլ ընկնում են դրա ազդեցության տակ։ Նկարում՝ [[3.27]], [[8.2.2]]։",
    137: "B «Մաքսային կետ» և C «Վտանգ» նշանները պահանջում են կանգնել կամ երթևեկությունը շարունակել միայն համապատասխան թույլտվությունից հետո։ A-ն տեղեկատու նշան է, իսկ D-ն «Կանգառն առանց կանգառի արգելվում է» նշան է, որի պահանջը կանգառից հետո կարելի է կատարել առանց հատուկ թույլտվության։ Նկարի նշանները՝ [[3.17.1]], [[3.17.2]], [[2.5]]։",
    138: "Հավասարազոր ճանապարհների հատման նախազգուշացնող նշանից հետո խաչմերուկը կարող է հանդիպել նվազագույնը 50 մ հեռավորության վրա՝ բնակավայրի պայմաններում։ Այդ պատճառով վարորդը պետք է նախապես պատրաստ լինի աջ կողմից մոտեցող տրանսպորտային միջոցներին զիջելուն։ Նկարում՝ [[1.6]]։",
    139: "Քարշակման համար թույլատրելի ուղղությունը որոշվում է սլաքներով ու բեռնատարների արգելքի նշանով։ Միայն A ուղղությունն է համապատասխանում նշված թույլտվությանը և չի մտնում արգելված ուղղության մեջ․ քարշակելիս պետք է նաև հաշվի առնել կապակցման ամրությունն ու անվտանգ հեռավորությունը։ Նկարում՝ [[3.4]], [[6.15.1]]։",
    140: "Բնակավայրում հատուկ երթևեկության կանոնները սկսում են գործել սպիտակ հիմնագույնով «Բնակավայրի սկիզբ» նշանն անցնելուց հետո․ կապույտ հիմնագույնով անվանացուցանակը այդ ռեժիմը չի սահմանում։",
    141: "Եռանկյուն նշանի վրա տրամվայի պատկերն զգուշացնում է տրամվայի գծերի հետ հատման մասին։ Խաչմերուկին մոտենալիս վարորդը պետք է գնահատի տրամվայի առաջնահերթությունը և պատրաստ լինի զիջելու՝ ըստ իրավիճակի ու ազդանշանների։ Նկարում՝ [[1.5]]։",
    142: "Մեքենաների միջև նվազագույն հեռավորության նշանը պարտադրում է պահել առնվազն 70 մ միջտարածություն, իսկ ներքևի ցուցանակը ցույց է տալիս, որ այդ պահանջը գործում է 900 մ երկարությամբ հատվածում։ Նշված հեռավորությունը պետք է պահպանվի ամբողջ այդ գոտում։ Նկարում՝ [[3.16]], [[8.2.1]]։",
    143: "Նշված գոտու ուղղությունների սլաքները ցույց են տալիս, որ կարելի է շարունակել ձախ կամ ուղիղ։ Վարորդը պետք է նախապես զբաղեցնի համապատասխան գոտին և չփոխի այն խաչմերուկի ներսում՝ եթե դա հակասում է գծանշմանը։ Նկարում՝ [[5.15.1]]։",
    144: "Եռանկյուն նշանը և դեպի գծանց հեռավորությունը նվազեցնող կարմիր-սպիտակ շերտավոր ցուցանակը տեղեկացնում են, որ 150–300 մ հետո հանդիպելու եք առանց ուղեփակոցի երկաթուղային գծանցի։ Նման գծանցին մոտենալիս պետք է դանդաղել, դիտել երկու ուղղությամբ և համոզվել, որ գնացք չի մոտենում։ Նկարում՝ [[1.2]], [[1.4.1]]։",
    145: "Կայանումը թույլատրվում է, քանի որ նշված տեղը գտնվում է կանգառն արգելող հատվածից դուրս՝ սահմանը ցույց տվող ցուցանակի համապատասխան կողմում։ Կարմիր X-ը կանգառն արգելում է նշանի ազդեցության ուղղությամբ, իսկ սլաքը հստակեցնում է, թե որտեղ է ավարտվում այդ հատվածը։ Նկարում՝ [[3.27]], [[8.2.3]]։",
    146: "5 տոննա բեռնատարին աջ շրջադարձ պարտադրում է B կապույտ շրջանաձև նշանը՝ աջ սլաքով․ այն պարտադիր ուղղություն է բոլոր նշանի ազդեցության տակ գտնվող մեքենաների համար։ A-ն ուղղության տեղեկատվական նշան է, իսկ C-ն բեռնատարի երթուղու ցուցիչ է։ Նկարի նշանները՝ [[6.10.2]], [[4.1.2]], [[6.15.1]]։",
    147: "3 տոննա թույլատրելի առավելագույն զանգված ունեցող բեռնատարը չի գերազանցում 3.5 տոննայի շեմը, ուստի բեռնատարների համար նախատեսված արգելքը դրա վրա չի տարածվում։ Լրացուցիչ ցուցանակով տրված ուղղության պահանջն էլ վերաբերում է միայն նկարում նշված տրանսպորտային միջոցների տեսակին։ Նկարում՝ [[3.4]], [[4.1.1]], [[8.4.1]]։",
    148: "Ձայնային ազդանշան տալն արգելված է, բացառությամբ այն դեպքի, երբ ազդանշանը անհրաժեշտ է ճանապարհատրանսպորտային պատահարը կանխելու համար։ Անտառում, բնակավայրում կամ պարզապես ուշադրություն գրավելու նպատակով ազդանշան տալը այդ բացառության մեջ չի մտնում։ Նկարում՝ [[3.26]]։",
    149: "Արհեստական անհարթությունը ցույց է տրվում A կապույտ քառակուսի տեղեկատվական նշանով։ B եռանկյունը նախազգուշացնում է անհարթության մասին, իսկ C-ն՝ ճանապարհի անհարթ հատվածի մասին, բայց հենց A-ն է նշում արհեստական անհարթության տեղը։ Նկարի նշանները՝ [[5.20]], [[1.17]], [[1.16]]։",
    150: "Կապույտ շրջանաձև աջ սլաքը պարտադրում է աջ շարժվել, ուստի միայն A հետագիծն է թույլատրելի։ B-ն հակառակ ուղղությամբ մանևր է և հակասում է նշանի հրահանգին։ Նկարում՝ [[4.1.2]]։",
    151: "A գլխավոր ճանապարհի նշանը և C-ի խաչմերուկի նախազգուշացնող նշանը ցույց են տալիս, որ վարորդը գլխավոր ճանապարհի վրա է և ունի առավելություն հատվող երկրորդական ճանապարհի նկատմամբ։ B նշանը հանդիպակաց հոսքի հետ նեղ հատվածի առաջնահերթության մասին է, ոչ թե խաչմերուկում գլխավոր ճանապարհի։ Նկարի նշանները՝ [[2.1]], [[2.6]], [[1.2.1]]։",
    152: "Վազանցը թույլատրվում է, եթե նշանի ազդեցության սահմանափակումը տվյալ տրանսպորտային միջոցի կամ իրավիճակի վրա չի տարածվում և մանևրը անվտանգ է։ Պետք է հատկապես ստուգել հանդիպակաց գոտու տեսանելիությունը, գծանշումը և վազանցվող մեքենայի արագությունը։ Նկարում՝ [[3.20]]։",
    153: "Կայանման նշանի տակ բեռնատարի պատկերով լրացուցիչ ցուցանակը ցույց է տալիս, որ տվյալ տեղը նախատեսված է համապատասխան տեսակի մեքենայի համար։ Նկարում բեռնատարը կանգնած է այդ սահմանափակմամբ նախատեսված վայրում, ուստի խախտել է կայանման կանոնները։ Նկարում՝ [[6.4]], [[8.4.1]]։",
    154: "Միակողմ երթևեկության նշանի պահանջով խաչմերուկը պետք է անցնել սլաքի ուղղությամբ։ B հետագիծն է թույլատրվում կատարել՝ առանց հակառակ հոսք դուրս գալու կամ պարտադիր ուղղության նշանին հակասելու։ Նկարում՝ [[5.5]]։",
    155: "Կենտ օրերին կանգառի կամ կայանման սահմանափակումները գործում են նշանների սահմանած ժամերին, իսկ 19:00-ից հետո կարող է սկսվել թույլատրելի հերթագայման ժամանակահատվածը։ Այդ պահին կայանել կարելի է՝ եթե մեքենան չի խոչընդոտում և չի խախտում այլ արգելք։ Նկարի նշանները՝ [[3.29]], [[3.30]]։",
    156: "B և C նշաններն են ցույց տալիս այն վայրը կամ գոտին, որտեղ վարորդը պետք է զիջի երթևեկելի մասը հատող հետիոտներին։ A եռանկյուն նախազգուշացնող նշանը միայն հայտնում է հետիոտների հնարավոր ներկայության մասին, բայց ինքնուրույն անցման տեղ չի սահմանում։ Նկարի նշանները՝ [[1.22]], [[5.19.1]], [[5.21]]։",
    157: "Հանդիպակաց երթևեկությամբ ճանապարհի սկզբին մոտենալու մասին նախազգուշացնում է A նշանը՝ երկու հակառակ ուղղություններով սլաքներով։ Այն վարորդին հիշեցնում է, որ առջևում կհանդիպեն հակառակ ուղղությամբ ընթացող մեքենաներ։ Նկարում՝ [[1.21]]։",
    158: "Արգելքի գոտում գտնվող սեփական աշխատավայր կամ բնակության վայր հասնելու համար թույլատրվում է մուտք գործել՝ պահպանելով նշանի սահմանած օրերի ու ժամանակի պայմանները։ Ցուցանակը ցույց է տալիս աշխատանքային օրերի ժամանակացույցը, բայց տեղացիների համար մուտքի բացառությունը գործում է բոլոր օրերին։ Նկարում՝ [[3.2]], [[8.5.2]]։",
    159: "Բեռնատարների երթևեկության արգելքը չի վերաբերում 3.5 տոննայից ոչ ավելի թույլատրելի առավելագույն զանգված ունեցող թեթև մարդատարին, նույնիսկ եթե այն կցորդ է քարշակում։ Կցորդը ինքնին մեքենան բեռնատար չի դարձնում, ուստի խաչմերուկում ուղիղ երթևեկել թույլատրվում է։ Նկարում՝ [[3.4]]։",
    160: "Կապույտ ուղղանկյուն նշանը ուղղության ցուցիչ է և տվյալ դեպքում տեղեկացնում է ճանապարհի ուղղության մասին, այլ ոչ թե պարտադիր սահմանափակում է խաչմերուկի բոլոր մանևրները։ Հետևաբար թույլատրված են բոլոր նշված ուղղությունները, եթե դրանք չեն հակասում մյուս նշաններին կամ գծանշմանը։ Նկարում՝ [[6.10.2]]։",
    161: "Նշանը ցույց է տալիս խաչմերուկում ճանապարհների դասավորությունն ու շարժման ուղղությունները։ Այն տեղեկատվական սխեմա է, որի սլաքներով վարորդը նախապես ընտրում է իրեն անհրաժեշտ գոտին։ Նկարում՝ [[6.9.3]]։",
    162: "B նշանի վրա հետադարձի սլաքի հետ նշված 15 մ-ը ցույց է տալիս հետադարձի համար նախատեսված գոտու երկարությունը։ A նշանի 50 մ-ը հեռավորության ցուցանակ է, ոչ թե այդ գոտու չափը։ Նկարում՝ [[6.3.2]], [[8.2.1]]։",
    163: "Սայթաքուն ճանապարհի նախազգուշացնող նշանը բնակավայրում տեղադրվում է վտանգավոր հատվածից առնվազն 50 մ առաջ։ Այդ տարածությունը վարորդին հնարավորություն է տալիս աստիճանաբար նվազեցնել արագությունը և խուսափել կտրուկ արգելակումից։ Նկարում՝ [[1.15]]։",
    164: "Կանգառն արգելող նշանի ազդեցությունը չի տարածվում միայն նշված ճանաչման նշանով կահավորված մոտոսայլակների և ավտոմոբիլների վրա։ Այլ մեքենաները պետք է ենթարկվեն կանգառի արգելքին։ Նկարում՝ [[3.27]], [[tsr-9.13]]։",
    165: "Խաչմերուկում տեղադրված նշանների և գծանշման համադրությունը թույլ է տալիս շարունակել բոլոր նշված ուղղություններով։ Պարտադիր սլաքը ցույց է տալիս հիմնական ուղղությունը, իսկ տվյալ խաչմերուկի կազմակերպումը թույլ է տալիս նաև մյուս մանևրները։ Նկարում՝ [[4.1.1]]։",
    166: "60 կմ/ժ արագությամբ կարելի է երթևեկել B և C նշանների ազդեցության ներքո․ կապույտ շրջանը սահմանում է նվազագույն արագություն, իսկ կապույտ քառակուսին՝ առաջարկվող արագություն։ A կարմիր եզրագծով նշանը սահմանում է 50 կմ/ժ առավելագույն արագություն, ուստի 60-ը կխախտի այն։ Նկարի նշանները՝ [[3.24]], [[4.6]], [[6.2]]։",
    167: "Կայանման վայրի նշանն ու դրա ներքևի տրանսպորտային միջոցի պատկերով ցուցանակը թույլատրում են տվյալ տեղում կանգնել նշված տեսակի մեքենաներին։ Նկարի մեքենաներից ոչ մեկը չի խախտում այդ սահմանափակումը, եթե կայանումը չի խանգարում երթևեկությանը կամ հետիոտներին։ Նկարում՝ [[6.4]], [[8.4.3]]։",
    168: "Աջ շրջադարձն արգելող նշանի պայմաններում թույլատրվում են A կամ C հետագծերը, որոնք չեն կատարում արգելված աջ շրջադարձ։ B հետագիծը գնում է դեպի աջ և հակասում է նշանի պահանջին։ Նկարում՝ [[3.18.1]]։",
    169: "B և C ցուցանակներն են տարածում իրենց հետ օգտագործված նշանի ազդեցությունը համապատասխան մեքենաների վրա։ Թեթև բեռնատարը՝ մինչև 3.5 տոննա թույլատրելի առավելագույն զանգվածով, դասակարգվում է նկարում համապատասխան նշված տրանսպորտային միջոցների խմբում։ Նկարի ցուցանակները՝ [[8.4.1]], [[8.4.3]], [[8.4.4]]։",
    170: "Երկու և ավելի ուղիներով երկաթուղային գծանցը ցույց է տալիս C՝ բազմագիծ գծանցի խաչաձև նշանը։ A-ն և B-ն նախազգուշացնում են գծանցի մասին ու ցույց են տալիս մոտեցման հեռավորությունը, բայց ուղիների քանակը հստակեցնում է հենց C-ն։ Նկարի նշանները՝ [[1.2]], [[1.1]], [[1.3.2]]։",
    171: "Շրջանաձև երթևեկության նշանը պահանջում է հանգույցում շարժվել սլաքների ուղղությամբ։ Նշված հետադարձ հետագիծը հակառակվում է շրջանաձև շարժման ուղղությանը, հետևաբար արգելվում է։ Նկարում՝ [[4.3]]։",
    172: "Կայանելն արգելող նշանի ազդեցության գոտում կամրջի տակ կայանումը թույլատրված չէ։ Նշանի ազդեցության սկիզբն ու վերջը պետք է որոշել դրա լրացուցիչ ցուցանակով և տեղադրման դիրքով, ոչ միայն կամրջի եզրով։ Նկարում՝ [[3.28]]։",
    173: "Նկարի նշանները զգուշացնում են ուղեփակոցով երկաթուղային գծանցին մոտենալու մասին։ Եռանկյուն նշանն ու կարմիր-սպիտակ մոտեցման ցուցիչները հերթով ցույց են տալիս գծանցի հեռավորությունը, ուստի վարորդը պետք է նվազեցնի արագությունը և պատրաստ լինի կանգնել։ Նկարի նշանները՝ [[1.1]], [[1.4.1]], [[1.4.2]]։",
    174: "Նկարի նշանները թույլատրում են հետադարձ կատարել, քանի որ դրանցից ոչ մեկը հետադարձի արգելք չի սահմանում․ ձախ շրջադարձի արգելքը և դեպի աջ ուղղության ցուցիչը տարբեր մանևրների են վերաբերում։ Հետադարձը, այնուամենայնիվ, պետք է կատարել անվտանգ տեղում և չխանգարել մյուսներին։ Նկարի նշանները՝ [[4.1.3]], [[3.18.2]], [[6.10.2]]։",
    175: "Գոտիների վերևում գտնվող սլաքները ցույց են տալիս, որ տվյալ գոտուց թույլատրվում են ձախ շրջադարձը և հետադարձը։ Պետք է ընտրել այդ սլաքներով նշված գոտին և մանևրի ընթացքում պահպանել խաչմերուկի գծանշումը։ Նկարում՝ [[5.15.1]]։",
    176: "Եռանկյան վրա թունելի պատկերով նշանը զգուշացնում է առաջիկա թունելի մասին։ Լրացուցիչ տեղեկությամբ պարզվում է, որ թունելում բացակայում է արհեստական լուսավորությունը, ուստի պետք է միացնել լուսարձակները և պահպանել անվտանգ արագություն։ Նկարում՝ [[1.31]]։",
    177: "Նշանի ազդեցության գոտում կանգառն արգելվում է, իսկ B տեղը գտնվում է այդ գոտուց դուրս։ Հետևաբար միայն B կետում է կարելի կանգառ կատարել՝ համոզվելով, որ տեսանելիությունը և ճանապարհային պայմանները անվտանգ են։ Նկարում՝ [[1.12.1]], [[3.27]]։",
    178: "B և C նշանների պայմաններում ձախ շրջադարձ թույլատրվում է, քանի որ դրանք ցույց են տալիս ճանապարհի ուղղությունն ու համապատասխան երթուղին, ոչ թե ձախ շրջադարձի արգելք։ A ուղղության ցուցիչը վարորդին սահմանափակում է միայն դեպի աջ։ Նկարի նշանները՝ [[6.10.2]], [[5.7.1]], [[6.15.1]]։",
    179: "Հեծանիվի պատկերով եռանկյուն նշանը նախապես զգուշացնում է հեծանվային արահետի հետ հատման մասին։ Խաչմերուկին մոտենալիս պետք է դանդաղել և զիջել հեծանվորդներին, եթե նրանք հատում են ճանապարհը։ Նկարում՝ [[1.24]]։",
    180: "Կայանման նշանի տակ մեքենայի դասը ցույց տվող ցուցանակը սահմանափակում է դրա ազդեցությունը թեթև մարդատարների և մոտոցիկլների վրա։ Այլ տեսակի տրանսպորտային միջոցների վարորդների համար այդ նշանը նույն սահմանափակումը չի ստեղծում։ Նկարում՝ [[6.4]], [[8.4.3]]։",
    181: "Կանգ առնելուց հետո առանց թույլտվության երթևեկությունը վերսկսել չի կարելի 5-րդ «Վտանգ» նշանի դեպքում։ Այն պահանջում է կանգնել և շարունակել միայն համապատասխան մարմնի թույլտվությամբ, մինչդեռ սովորական STOP նշանը պահանջում է կանգառ ու զիջում, բայց ինքնին թույլտվություն սպասել չի պարտադրում։ Նկարի նշանները՝ [[2.5]], [[2.5]], [[3.1]], [[3.17.2]]։"
};

