    3: "Նշանների բացակայության դեպքում հերթը որոշվում է աջից մոտեցողին զիջելով․ կապույտը նախ թողնում է մյուսներին։ Ճիշտ պատասխանն է՝ «Կապույտ ավտոմոբիլը։»։",
    4: "Կապույտ մեքենան գլխավոր ճանապարհով է մոտենում․ երկրորդական ճանապարհից եկողները զիջում են։ Նշանները՝ [[2.1]], [[8.13]]։ Ճիշտ պատասխանն է՝ «Առաջինը։»։",
