    "6": " ՀՀ կանոններով կայանելն արգելվում է երկաթուղային գծանցից 50 մ-ից մոտ։ ",
    "7": "Ավտոբուսի կանգառի տարածքում ուղևոր իջեցնել կարելի է միայն եթե դա չի խոչընդոտում ընդհանուր օգտագործման տրանսպորտին։ Նկարում այդ պայմանը պահպանված է, ուստի կարճ կանգառը թույլատրվում է։",
