    "10": "Կայանման նշանի լրացուցիչ ցուցանակը արտոնությունը սահմանում է միայն հաշմանդամների կողմից ղեկավարվող տրանսպորտի և միացված հաշվիչով տաքսիների համար։ Մյուսները չեն կարող օգտվել այդ հատուկ տեղից։",
    "11": "Դեղին զիգզագ գծանշումը կանգառի կետ է նշում ընդհանուր օգտագործման տրանսպորտի համար։ Այն ցույց է տալիս կանգառի տարածքը, ոչ թե սովորական կայանատեղի։",
    "12": "Դեղին հոծ գիծը եզրաքարի/երթևեկելի մասի եզրի մոտ նշում է այն հատվածը, որտեղ արգելվում են և՛ կանգառը, և՛ կայանումը։",
    "13": "Կայանման տեղերի սահմանային գծերը թույլատրվում է հատել՝ կայանատեղի մտնելու կամ դուրս գալու համար։ Այդ գծանշումը չի արգելում դրա հատումը, բայց չի վերացնում մյուս կանոնները։",
