    "1": "Բնակավայրից դուրս թեթև մարդատար ավտոմոբիլի ընդհանուր առավելագույն արագությունը 90 կմ/ժ է, եթե նշաններով ավելի ցածր սահմանափակում չի դրված։",
    "2": "Մարդատար տեղափոխող կահավորված թափքով բեռնատարի համար սահմանված առավելագույնը 60 կմ/ժ է․ լրացուցիչ ուղևորները և թափքի կառուցվածքը պահանջում են ավելի զգույշ ընթացք։",
