const group9Commentaries = {
    "1": "Կանգնած մեքենայի վրա կարմիր փարոսիկը պահանջում է մոտեցողներին կանգնել և շարունակել միայն պատասխանատու անձից թույլտվություն ստանալուց հետո։",
    "2": "Կապույտ փարոսիկն ու հատուկ ձայնային ազդանշանը միացրած մեքենային պետք է ճանապարհ տալ՝ ապահովելով դրա անխոչընդոտ անցումը։",
    "3": "Մոպեդի մոտակա լույսը պետք է միացված լինի երթևեկության ընթացքում նաև ցերեկը, որպեսզի այն ավելի տեսանելի լինի։",
    "4": "Նախազգուշացնող նշանի առկայությունն ինքնին վարորդին չի պարտադրում ազդանշան տալ․ շրջադարձի նշանը նախազգուշացնում է ճանապարհի կորության մասին, ոչ թե վարորդի մանևրի։",
    "5": "Վերադասավորումից առաջ ցուցիչը միացվում է նախօրոք՝ մինչև գոտին փոխելը, որպեսզի մյուսները հասցնեն արձագանքել։",
    "6": "Ցուցիչը պետք է տալ նախքան երթևեկության ուղղությունը փոխելը․ ազդանշանը նախազգուշացնում է մանևրի մասին, բայց ինքնին առավելություն չի տալիս։",
    "7": "Ձեռքով ազդանշանը դադարեցվում է մանևրն սկսելուց անմիջապես առաջ, որպեսզի ձեռքը վերադառնա ղեկին մանևրի ընթացքում։",
    "8": "Կանգառից առաջ վարորդը պարտավոր է նախապես տեղեկացնել հետևից և կողքից ընթացողներին՝ անկախ կանգառի պատճառից։",
    "9": "Գծանցի վրա հարկադրաբար կանգնելիս ընդհանուր տագնապի ձայնային ազդանշանը մեկ երկար և երեք կարճ ազդանշանների հաջորդականությունն է։",
    "10": "Եթե շրջադարձի ցուցիչը չի աշխատում, ձեռքով տրված ազդանշանը պահվում է մինչև մանևրի մեկնարկը, ապա դադարեցվում է՝ երկու ձեռքով ղեկը կառավարելու համար։",
    "11": "Երկաթուղային գծանցի վրա ընդհանուր տագնապը տալիս են մեկ երկար և երեք կարճ ձայնային ազդանշանով, որպեսզի վտանգը լսելի լինի բոլորին։",
    "12": "Նկարում առաջին վարորդի ձախ ձեռքը հորիզոնական պարզած է։ Դա ձախ շրջադարձի կամ հետադարձի ձեռքի ազդանշանն է։",
    "13": "Կարմիր փարոսիկով կանգնած մեքենային մոտենալիս պետք է կանգնել և սպասել թույլտվության․ կարմիր ազդանշանն արգելում է շարունակել ընթացքը։",
    "14": "Դեղին կամ նարնջագույն փարոսիկը նախազգուշացնում է վտանգի կամ հատուկ աշխատանքի մասին, բայց մյուսներին զիջելու պարտականություն չի ստեղծում և առավելություն չի տալիս։",
    "15": "Կապույտ փարոսիկն ու հատուկ ձայնային ազդանշանը միասին միացրած մեքենային պետք է զիջել և չխոչընդոտել դրա անցմանը։",
    "16": "Նկարում շտապօգնության մեքենան մոտենում է միացված կապույտ փարոսիկով և ձայնային ազդանշանով։ Այն առաջինն է անցնում, իսկ կապույտ ավտոմեքենան անցնում է երրորդը՝ կարմիրի հետ միաժամանակ, երբ հատուկ մեքենային արդեն ճանապարհ է տրվել։",
    "17": "Կապույտ-կարմիր փարոսիկներն ու ձայնային ազդանշանը պահանջում են դանդաղեցնել և ճանապարհ տալ թե՛ հատուկ մեքենային, թե՛ նրա ուղեկցած տրանսպորտային շարասյանը։",
    "18": "Նկարում ջրցան մեքենայի դեղին փարոսիկը նախազգուշացնում է աշխատանքի կամ վտանգի մասին, բայց առավելություն չի տալիս։ Հետևաբար վարորդները ղեկավարվում են հիմնական/երկրորդական ճանապարհի նշաններով, և առաջնահերթ է թեթև մարդատարը։",
    "19": "Նկարում հրշեջ մեքենան միացրել է հատուկ ազդանշանները, ուստի այն անցնում է առաջինը։ Սև մեքենան գլխավոր ճանապարհի վրա է և անցնում է հաջորդը, իսկ կանաչը զիջում է։",
    "20": "Թեթև մարդատարի համար կանաչը թույլատրում է ընթացքը, բայց հրշեջ մեքենան հատուկ փարոսիկով ու ձայնային ազդանշանով խաչում է դրա ճանապարհը։ Մյուս վարորդը պետք է զիջի հատուկ մեքենային։",
    "21": "Խաչմերուկի հերթը որոշվում է գլխավոր ճանապարհի ուղղության ցուցանակով և հատուկ ազդանշաններով։ Կապույտ մեքենան պետք է զիջի գլխավոր ուղղության մեքենաներին և, հետևաբար, անցնում է վերջինը։",
    "22": "Դեղին/նարնջագույն փարոսիկը միայն զգուշացնում է վտանգի մասին․ այն չի տալիս երթևեկության առավելություն և չի ազատում ընդհանուր կանոններից։",
    "23": "Լուսնասպիտակ փարոսիկով և ձայնային ազդանշանով մեքենան ազդանշանն օգտագործում է ոստիկանների կամ այլ անձանց ուշադրությունը գրավելու համար, ոչ թե երթևեկության առավելություն ստանալու։",
    "24": "Կապույտ փարոսիկը միայնակ առավելություն չի տալիս․ վարորդը առավելություն ունի, երբ միացված են և՛ կապույտ փարոսիկը, և՛ հատուկ ձայնային ազդանշանը։",
    "25": "Վազանցն արգելվում է երկաթուղային գծանցից առաջ 100 մ հատվածում և հենց գծանցի վրա՝ հանդիպակաց գոտի դուրս գալու վտանգի պատճառով։",
    "26": "Գլխավոր համարվող ճանապարհի վրա գտնվող խաչմերուկում էլ վազանցը արգելված է․ առավելության իրավունքը չի վերացնում խաչմերուկներում վազանցի արգելքը։",
    "27": "Նկարում ավտոմեքենան պետք է վազանցի միաժամանակ մի քանի տրանսպորտային միջոցի՝ դուրս գալով հանդիպակաց գոտի։ Պատկերված խիտ հոսքում բավարար ազատ տարածք և անվտանգ վերադառնալու հնարավորություն չկա, ուստի վազանց սկսել չի թույլատրվում։",
    "28": "Խաչմերուկներում վազանցը չի թույլատրվում, քանի որ հատվող հոսքերը կարող են հայտնվել տեսադաշտից դուրս։",
    "29": "Վազանցն արգելվում է նշված երկու դեպքերում էլ, քանի որ դրանցից յուրաքանչյուրը վտանգավոր է կամ կանոնով սահմանված արգելքի գոտի է։",
    "30": "Նկարում ավտոգնացքը շարժվում է 30 կմ/ժ-ից ոչ ավելի դանդաղ, բայց խաչմերուկն ու «խաչմերուկ» նախազգուշացնող նշանը սահմանափակում են վազանցը։ Դանդաղ մեքենա լինելու հանգամանքը չի վերացնում տվյալ արգելքը։",
    "31": "Նկարում ճանապարհային աշխատանքների նշանը և պատնեշը ցույց են տալիս վտանգավոր, նեղացված հատված։ Կանաչ մեքենան պետք է սպասի և չվազանցի՝ հանդիպակաց գոտի մտնելով այդտեղ։",
    "32": "Կարմիր մեքենան վազանցելիս պետք է դուրս գա հանդիպակաց գոտի՝ հավասարազոր/հատվող ճանապարհի խաչմերուկի մոտ։ Խաչմերուկում վազանցն արգելված է՝ անկախ գլխավոր ճանապարհով լինելուց։",
    "33": "Նկարում մեքենաներն արդեն անցել են երկաթուղային գծանցի նշանների տեղը, իսկ իրենց ուղղությունների միջև ընդհատվող գիծն է։ Հետևաբար գծանցից առաջ գործող 100 մ վազանցի արգելքը այստեղ չի գործում, և վազանցը թույլատրվում է՝ եթե անվտանգ է։",
    "34": "Վազանցը շարժման մեջ գտնվող մեկ կամ մի քանի մեքենայից առաջ անցնելն է՝ դրա համար սկզբնական գոտուց դուրս գալով և հետո վերադարձով։ Նույն գոտում ավելի արագ գնալը վազանց չի համարվում։",
    "35": "Մթության կամ անբավարար տեսանելիության ժամանակ մեխանիկական տրանսպորտի վրա պետք է աշխատեն մոտակա կամ հեռահար լապտերները՝ ճանապարհը տեսնելու և մեքենան տեսանելի դարձնելու համար։",
    "36": "Մոտոցիկլի մոտակա լույսը միացված է պահվում երթևեկության ամբողջ ընթացքում՝ նաև ցերեկը։",
    "37": "Շլանալու դեպքում նախ միացրեք վթարային ազդանշանը և նվազեցրեք արագությունը, անհրաժեշտության դեպքում կանգնեք։ Մի նայեք ուղիղ հանդիպակաց լույսին և մի շարունակեք կուրացած վիճակում։",
    "38": "Ձայնային ազդանշանը կիրառվում է միայն ճանապարհատրանսպորտային պատահարը կանխելու անհրաժեշտության դեպքում․ այն չի օգտագործվում շտապելու կամ մյուսներին անհիմն զգուշացնելու համար։",
    "39": "Չլուսավորված ճանապարհի մութ հատվածում պետք է միացված լինեն մոտակա կամ հեռահար լապտերները՝ ըստ հանդիպակաց և համընթաց մեքենաների առկայության։",
    "40": "Հետին հակամառախուղային լույսը կիրառվում է միայն անբավարար տեսանելիության ժամանակ, քանի որ պարզ պայմաններում այն կարող է շլացնել հետևից եկողներին։",
    "41": "Հեռահար լույսը մոտակայի փոխարկեք հանդիպակաց մեքենայից առնվազն 150 մ առաջ, ինչպես նաև ավելի շուտ, եթե լույսը կարող է շլացնել վարորդին։",
    "42": "Լապտեր-լուսարձակը կարելի է օգտագործել բնակավայրից դուրս միայն այն ժամանակ, երբ մոտակայքում չկան հանդիպակաց կամ համընթաց մեքենաներ, որոնց վարորդները կարող են շլանալ։",
    "43": "Նկարում «Երեխաներ» նախազգուշացնող նշանն է։ Բնակավայրում վտանգավոր հատվածից առաջ այն տեղադրվում է 50–100 մ հեռավորության վրա, որպեսզի վարորդը հասցնի նվազեցնել արագությունը։",
    "44": "Գյուղատնտեսական կամ շինարարական մեքենան գծանցով փոխադրել կարելի է, եթե այն բերված է տրանսպորտային վիճակի՝ չի գերազանցում թույլատրելի չափերը և կարող է անվտանգ անցնել։",
    "45": "Երկաթուղային գծերը հատում են միայն դրա համար նախատեսված գծանցներում․ այլ տեղում հատելը վտանգավոր և արգելված է։",
    "46": "Ուղեփակոցը ինքնակամ բացել կամ շրջանցել չի կարելի, նույնիսկ ծառայողական առաջադրանքի ժամանակ․ պետք է ենթարկվել գծանցի ազդանշաններին և պատասխանատուների կարգադրություններին։",
    "47": "Մեքենաներն ու մեխանիզմները երկաթուղային գծանցով կարող են անցնել միայն տրանսպորտային վիճակում՝ առանց թույլատրելի չափերը խախտելու և անվտանգ անցումը վտանգելու։",
    "48": "Գծանցին մոտենալիս պետք է միաժամանակ պահպանել նշանների ու լուսացույցի պահանջները, դիտարկել ուղեփակոցը և համոզվել, որ անցումը բաց է։ Հետևաբար գործում են թվարկված բոլոր պահանջները։",
    "49": "«Ավտոմայրուղի» նշանով ճանապարհով հետիոտնի տեղաշարժն արգելված է․ այն նախատեսված է միայն համապատասխան մեխանիկական տրանսպորտային միջոցների համար։",
    "50": "Եթե մեքենայի տեխնիկական կամ իրական վիճակով արագությունը չի կարող գերազանցել 40 կմ/ժ, դրանով ավտոմայրուղով երթևեկել չի թույլատրվում, քանի որ այն կխոչընդոտի արագ հոսքին։",
    "51": "Վթարային ազդանշանը պետք է միացնել կանոնով նախատեսված երկու իրավիճակներում էլ՝ հարկադիր կանգառի և ճանապարհատրանսպորտային պատահարի դեպքում։",
    "52": "Վթարային լուսային ազդանշանը միացվում է բոլոր թվարկված դեպքերում, երբ մեքենան կանգնած է վտանգավոր կամ անսովոր վիճակում և պետք է զգուշացնել մյուսներին։",
    "53": "Վթարային կանգառի նշանը տեղադրվում է առնվազն 15 մ հեռու բնակավայրում և առնվազն 30 մ՝ բնակավայրից դուրս, որպեսզի մյուսները ժամանակին նկատեն խոչընդոտը։",
    "54": "Տրված երկու իրավիճակներում էլ վթարային լուսային ազդանշանը պարտադիր է, քանի որ վարորդը պետք է զգուշացնի հետևից մոտեցողներին։",
    "55": "Երկու նկարագրված դեպքերում էլ վթարային ազդանշանը պետք է միացվի՝ վտանգը և մեքենայի հարկադիր/անսովոր կանգնած վիճակը նշելու համար։",
    "56": "Բնակելի գոտում հետիոտները կարող են տեղաշարժվել նաև երթևեկելի մասով՝ չստեղծելով անհարկի խոչընդոտ։ Վարորդը պետք է շարժվի դանդաղ և նրանց զիջի։",
    "57": "Խաչմերուկը կարգավորվող է, երբ երթևեկության հերթը որոշում է լուսացույցը կամ կարգավորողը․ երկու դեպքում էլ հերթականությունը կարգավորվում է։",
    "58": "Խաչմերուկից առաջ կարճ ասֆալտապատ հատվածը ինքնին հողային ճանապարհը հավասարազոր չի դարձնում ծածկույթով ճանապարհին։ Ճանապարհի կարգավիճակը որոշվում է ամբողջական ծածկույթի և նշանների հիման վրա։",
    "59": "Նկարի աջ տարբերակում թույլատրված սլաքները չեն հակասում արգելող նշանին․ կարելի է շարժվել նշված ուղղություններով։ Մյուս նկարներում նախատեսված հետադարձ/շրջադարձը արգելող նշանների հետ անհամատեղելի է։",
    "60": "Եթե լուսացույցի ազդանշանը հակասում է առավելության նշանին, վարորդը ղեկավարվում է լուսացույցով, քանի որ կարգավորվող խաչմերուկում դրա ազդանշանն է որոշում հերթը։",
    "61": "Դեղին լույսի կամ կարգավորողի բարձրացրած ձեռքի դեպքում կարելի է շարունակել միայն եթե կանգնելը հնարավոր չէ առանց կտրուկ արգելակման։ Հակառակ դեպքում կանգնում են։",
    "62": "Կարգավորողը սուլիչով հրավիրում է երթևեկության մասնակիցների ուշադրությունը, որպեսզի նրանք նկատեն և հետևեն իր ձեռքի ազդանշանին։",
    "63": "Նկարում կամրջի ցուցանակը սահմանում է 5 տ առավելագույն զանգված, իսկ բեռնատարներով կազմված ավտոգնացքի ընդհանուր զանգվածը 5 տ-ից ավելի է։ Այն գերազանցում է թույլատրելի սահմանը, ուստի կամրջով անցնելն արգելված է։",
    "64": "Նկարում վարորդը ձեռքը դուրս է պարզել՝ ձախ շրջադարձի/հետադարձի ազդանշան տալու համար։ Ձեռքով ազդանշանը թույլատրելի է, երբ շրջադարձի ցուցիչը բացակայում կամ անսարք է։",
    "65": "Բնակելի գոտուց երթևեկությունը սկսելիս վարորդը պետք է միացնի համապատասխան շրջադարձի ցուցիչը՝ իր մտադրությունը մյուսներին նախապես հայտնելու համար։",
    "66": "Պարեկային մեքենան առավելություն է ստանում միայն կապույտ փարոսիկն ու հատուկ ձայնային ազդանշանը միասին միացնելու դեպքում։ Միայն փարոսիկը բավարար չէ։",
    "67": "Երկաթուղային գծանցի վրա և դրանից առաջ 100 մ հատվածում հանդիպակաց գոտի դուրս գալով վազանցն արգելված է՝ գնացքի մոտենալու և տեսանելիության սահմանափակման վտանգի պատճառով։",
    "68": "Նկարում վարորդի ձեռքը բարձր է պարզած։ Դա տեղեկացնում է, որ նա պատրաստվում է արգելակել կամ դանդաղեցնել ընթացքը։",
    "69": "Ճանապարհատրանսպորտային պատահարի դեպքում վթարային լուսային ազդանշանը պետք է միացնել՝ կանգնած մեքենան վտանգի մասին նշելու համար։",
    "70": "Մոտոցիկլավարը ձախ ձեռքը պարզել է կողք։ Այդ ազդանշանը հայտնում է ձախ շրջադարձի կամ հետադարձի մտադրությունը։",
    "71": "Նկարում վարորդը ձախ ձեռքը արմունկից ծալած վեր է բարձրացրել․ սա աջ շրջադարձի ձեռքի ազդանշանն է։ Այն տեղեկացնում է մտադրության մասին, բայց վարորդը պետք է շրջադարձը կատարի միայն համոզվելով, որ դա անվտանգ է։",
    "72": "Վարորդի ձախ ձեռքը հորիզոնական պարզած է։ Այն նշանակում է ձախ շրջադարձ կամ հետադարձ կատարելու մտադրություն։",
    "73": "Նկարում մեքենան մտնում է ճանապարհային խաչմերուկ/փոխում ուղղությունը, ուստի ցուցիչով պետք է նախապես տեղեկացնել շրջադարձի մասին։ Առաջնահերթ ճանապարհով լինելը ազդանշանի պարտականությունը չի վերացնում։",
    "74": "Նկարում բեռնատարը դուրս է գալիս վազանցի՝ թույլատրելի գծանշմամբ և բավարար տեսանելիությամբ։ Ավտոբուսի 60 կմ/ժ արագությունն ինքնին վազանցը չի արգելում, եթե բեռնատարն անվտանգ ավարտում է մանևրը։",
    "75": "Նկարում առջևում գնացքի նախազգուշացնող նշանն է, իսկ մեքենաները մոտենում են գծանցին։ Վազանցն արգելված է հենց գծանցի վրա և դրանից առաջ 100 մ-ում։",
    "76": "Երկաթուղային գծանցի լուսաազդանշանը/փակվող ուղեփակոցը ցույց է տալիս, որ գնացքի անցումն արգելում է մուտքը։ Կանգնեք գծանցից առաջ և մի փորձեք անցնել։",
    "77": "Ուղեփակոցը բարձրացված է, բայց կարմիր ազդանշանն է որոշիչը․ կարմիրի ժամանակ գծանց մտնել չի կարելի։ Սպասեք մինչև ազդանշանն անջատվի և անցումն անվտանգ լինի։",
    "78": "Ուղեփակոցը փակ է և խոչընդոտում է անցումը։ Կանգնեք դրա առաջ և սպասեք բացվելուն, նույնիսկ եթե գնացքը դեռ չի երևում։",
    "79": "Նկարում խաչաձև նշանը ցույց է տալիս գծանցը, իսկ ձեր ուղղությամբ երթևեկող մեքենայի դիրքն ու ազդանշանը պահանջում են կանգնել։ Մի մտեք գծանց, մինչև արգելքը վերանա։",
    "80": "Գծանցի աշխատակիցը կանգնեցնող ազդանշան է տալիս։ Այդ ձեռքի ազդանշանը պարտադիր է, և վարորդը կանգնում է՝ անկախ ուղեփակոցի դիրքից։",
    "81": "Գծանցի լուսացույցները կարմիր խաչ են ցույց տալիս, հետևաբար կանգնեք և սպասեք։ Վազանցը կարելի է սկսել միայն գծանցն անցնելուց հետո, երբ գծանշումն ու տեսանելիությունը թույլ են տալիս։",
    "82": "Նկարում առջևում վազանցն ավարտելուց հետո հանդիպակաց երթևեկությունը դժվար է, կան նաև կանգնած/վթարված մեքենաներ։ Այդ վտանգավոր հատվածում հանդիպակաց գոտի դուրս գալով վազանցն արգելված է։",
    "83": "Մեքենան դուրս է գալիս իր գոտուց, անցնում առջևի տրանսպորտային միջոցից առաջ և վերադառնում գոտի․ սա վազանց է, ոչ թե պարզապես խոչընդոտի շրջանցում։",
    "84": "Ճանապարհի երկայնքով շարունակական գիծը և առաջիկա խոչընդոտի/մեքենայի դիրքը թույլ չեն տալիս մոտոցիկլից առաջ անցնել՝ հանդիպակաց գոտի դուրս գալով։ Ուստի վազանցն արգելված է։",
    "85": "Հանդիպակաց գոտիով վազանցը թույլատրելի է միայն եթե տեսանելի ճանապարհը բավարար է և մանևրը կարելի է ավարտել առանց հանդիպակացին կամ հետևից ընթացողին խանգարելու։ Երկու պայմանն էլ պարտադիր են։",
    "86": "Նկարում արագության սահմանափակման նշանն ու գծանշումները չեն արգելում վազանցը։ Թույլատրվում է, եթե հանդիպակաց գոտին ազատ է, տեսանելիությունը բավարար է, և վարորդը կարող է անվտանգ վերադառնալ։",
    "87": "Խաչմերուկի նախազգուշացնող նշանը ցույց է տալիս մոտակա հատումը։ Վազանցը թույլատրվում է միայն եթե մինչև խաչմերուկը մանևրը լիովին ավարտվում է և վազանցի այլ արգելք չկա։",
    "88": "Վազանցվող վարորդը չպետք է բարձրացնի արագությունը կամ այլ կերպ խանգարի վազանցն ավարտելուն․ վազանցողին ճանապարհ տալու պարտականությունը չի նշանակում արագացնել։",
    "89": "Նկարում տեղադրված է «Վազանցն արգելվում է» նշանը։ Այդ գոտում վազանց չի կարելի կատարել՝ անկախ նրանից, թե առջևի մեքենան դանդաղ է ընթանում։",
    "90": "Նկարում դանդաղընթաց տրակտորի նկատմամբ բեռնատարի զանգվածը 3 տ է, իսկ նշանը բեռնատարներով վազանցի արգելք է սահմանում ծանր բեռնատարների համար։ 3 տ բեռնատարին արգելքը չի վերաբերում, ուստի վազանցը թույլատրվում է՝ եթե անվտանգ է։",
    "91": "Նեղ և տեսանելիությամբ սահմանափակ ոլորանում երկու մեքենան իրար են մոտենում։ Բեռնատարը պետք է զիջի՝ հնարավորինս աջ շարժվելով կամ կանգնելով, որպեսզի հանդիպակաց մեքենան անվտանգ անցնի։",
    "92": "Հետիոտնային անցման վրա վազանցը արգելված է, քանի որ այնտեղ հետիոտնը կարող է հայտնվել մեքենայի առջևում և չերևալ վազանցողին։",
    "93": "Նկարում Ա հետագիծն է թույլատրելի, քանի որ վազանցը սկսում է այն հատվածում, որտեղ գիծը և ճանապարհի տեսանելիությունը թույլ են տալիս։ B-ն շարունակվում է խաչմերուկի/գոտու սահմանափակման մեջ և չի ավարտվում անվտանգ։",
    "94": "Նշանի պատկերն ու 500 մ ցուցանակը տեղեկացնում են, որ 500 մ հետո հանգստի վայր է։ Սա ուղղորդող տեղեկություն է, ոչ թե վտանգի կամ առաջնահերթության պահանջ։",
    "95": "Նկարում մեքենան հետևում է ճանապարհի կորությանը՝ առանց խաչմերուկում ուղղություն փոխելու կամ գոտի փոխելու։ Այդ պատճառով շրջադարձի ցուցիչ տալ պարտադիր չէ։",
    "96": "ի նկարում վարորդը ձեռքը ուղղահայաց վեր է բարձրացրել։ Դա ազդանշան է ընթացքը դանդաղեցնելու կամ կանգնելու մտադրության մասին։",
    "97": "Ցանկացած նախազգուշացնող ազդանշան միայն տեղեկացնում է մանևրի մասին․ այն վարորդին առավելություն չի տալիս և մյուսներին ճանապարհ զիջելու պարտականությունից չի ազատում։",
    "98": "Գլխավոր ճանապարհը խաչմերուկում թեքվում է աջ։ Այդ ուղղությամբ հետևելիս վարորդը փաստացի շրջադարձ է կատարում, ուստի աջ ցուցիչը պարտադիր է։",
    "99": "Մոտոցիկլավարը ձեռքը բարձրացրել է՝ տեղեկացնելով դանդաղեցնելու մասին, որպեսզի թեթև մարդատարին հնարավորություն տա անվտանգ միանալու կամ անցնելու։",
    "100": "Նշանի ցուցանակը ցույց է տալիս, որ գլխավոր ճանապարհն այս խաչմերուկում թեքվում է ձախ։ Ձախով շարունակելն իրական շրջադարձ է, հետևաբար ձախ ցուցիչը պարտադիր է։",
    "101": "Վազանցն ավարտելուց հետո ձախ ցուցիչը անջատվում է անմիջապես գոտի վերադասավորվելուց հետո։ Շարունակաբար միացրած պահելը կարող է մյուսներին շփոթեցնել հաջորդ մանևրի մասին։",
    "102": "Շրջանաձև երթևեկության մեջ հետադարձ կատարելու համար մեքենան ելքի ուղղությամբ շրջվում է աջ, հետևաբար միացվում է աջ շրջադարձի ցուցիչը։",
    "103": "Գոտիների նշաններն ու գծանշումը ցույց են տալիս, որ վարորդը փոխում է ընթացքի ուղղությունը։ Մանևրի մասին պետք է ազդարարել ցուցիչով նախապես։",
    "104": "Մոտոցիկլավարը ձախ ձեռքը պարզել է կողք։ Դա ձախ շրջադարձ կամ հետադարձ կատարելու ազդանշանն է։",
    "105": "Շրջադարձի ցուցիչը անջատվում է հենց մանևրն ավարտելուց հետո, որպեսզի մյուսները չկարծեն, թե մեքենան դեռ պատրաստվում է փոխել ուղղությունը։",
    "106": "Ճանապարհին անասուններ են հայտնվել, և վարորդը պետք է նախազգուշացնի մյուսներին համապատասխան ազդանշանով ու դանդաղեցնի։ Նշված իրավիճակում ազդանշան տալը պարտադիր է՝ վտանգը ժամանակին նկատելու համար։",
    "107": "Երկու մոտոցիկլավարներն էլ ձեռքով հայտնում են աջ շրջադարձի մասին․ մեկը ձեռքը պարզել է աջ, մյուսը՝ ձախ ձեռքը արմունկից բարձրացրել։ Երկուսն էլ իրավաչափ աջ ազդանշան են տալիս։",
    "108": "Կայանատեղիում կամ բենզալցակայանում ուղղություն փոխելիս կամ գոտի փոխելիս ևս պետք է ցուցիչ տալ․ մասնավոր տարածքը չի վերացնում ազդանշան տալու պարտականությունը։",
    "109": "Սպիտակ մեքենայի վարորդը ձեռքը դուրս է պարզել՝ տեղեկացնելով, որ պատրաստվում է սկսել երթևեկությունը/դուրս գալ կանգնած դիրքից։ Մանևրը պետք է կատարի՝ մյուսներին զիջելուց հետո։",
    "110": "Նշված հետագծով հետադարձն իրականացվում է երկու հաջորդական դիրքափոխությամբ։ Նախ աջ ցուցիչով շարժվեք դեպի եզրային դիրք, ապա ձախ ցուցիչով կատարեք հետադարձը՝ համոզվելով, որ ճանապարհն ազատ է։",
    "111": "Եթե կանգառը նախատեսվում է խաչմերուկից անմիջապես հետո, աջ ցուցիչը պետք է միացնել խաչմերուկն անցնելուց հետո։ Ավելի շուտ միացնելը կարող է մյուսներին մոլորեցնել, թե աջ եք շրջվում։",
    "112": "Վազանցն ավարտող վարորդը գոտի վերադառնալիս առավելություն չունի այդ գոտով ընթացողի նկատմամբ։ Նա պետք է զիջի և վերադասավորվի միայն անվտանգ բացվածք գտնելուց հետո։",
    "113": "Հատակից դուրս եկող ոստիկանության մեքենան միացրել է հատուկ փարոսիկն ու ձայնային ազդանշանը։ Մյուս վարորդները պետք է զիջեն և ապահովեն դրա անխոչընդոտ մուտքը։",
    "114": "Դեղին փարոսիկը զգուշացնում է աշխատանքային կամ վտանգավոր երթևեկության մասին, բայց առավելություն չի տալիս։ Ուղիղ ընթացողը չի պարտավոր զիջել միայն այդ փարոսիկի պատճառով։",
    "115": "Կանաչ լույսը ձեր ընթացքին թույլտվություն է տալիս, բայց խաչմերուկում արդեն շարժվող մասնակիցներին պետք է զիջել։ Նկարում մոտոցիկլն ու կողային մեքենան հատում են ձեր ուղին, հետևաբար ճանապարհ տվեք երկուսին։",
    "116": "Կարգավորվող խաչմերուկում կանաչ ազդանշանը թույլատրում է շարժվել, բայց տրամվայը/ավտոբուսը շարժվում է իր ազդանշանի ներքո։ Նկարում միայն ավտոբուսի ուղին է հատվում ձեր ընթացքի հետ, ուստի զիջեք նրան։",
    "117": "Ձախից մոտեցող մեքենայի վարորդն ունի առավելություն՝ ըստ պատկերված կարգավորման/հատվող ուղիների։ Շտապ ազդանշանով մեքենան նույնպես պետք է դիտարկել, բայց այս իրավիճակում զիջում է միայն ձախից մոտեցողին։",
    "118": "Նկարում ոստիկանության մեքենան շարժվում է հատուկ ազդանշաններով և հատում է ձեր ուղին։ Այդ մեքենային պետք է զիջել, անկախ գլխավոր ճանապարհի նշանից։",
    "119": "Ձախ շրջադարձի ուղին հատում է խաչմերուկով ընթացող մյուս տրանսպորտային միջոցների ուղղությունները։ Պետք է զիջել բոլոր այն վարորդներին, որոնց երթուղին հատվում է ձեր շրջադարձի հետ։"
};
